const e="ftzw9ImVrgE",t="ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary",g="a2",s="100+ Essential English Words for Daily Life | Slow English Vocabulary",n="https://www.youtube.com/watch?v=ftzw9ImVrgE",o={podcastLabel:"MissHoney A2",titleZh:"100+ 日常生活必備英文單字 |慢速英語詞彙",titleEn:"100+ Essential English Words for Daily Life | Slow English Vocabulary",levelTag:"A2",topicTag:"language"},a=JSON.parse(`[{"id":"scene-01","no":"01","titleZh":"第 1 段","titleEn":"Part 1","sentences":[{"en":"In this video, you'll learn the essential vocabulary you need in four different situations.","tc":"在本視頻中，您将學習在四種不同情况下所需的基本詞彙。","englishTokens":[{"type":"text","text":"In this video, you'll learn the "},{"type":"word","text":"essential","targetId":"word-essential","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-001-01"},{"type":"text","text":" vocabulary you need in four different situations."}]},{"en":"At the airport, at the grocery store, at the house, and in the kitchen.","tc":"在機場、在雜貨店、在家里、在廚房。","englishTokens":[{"type":"text","text":"At the "},{"type":"word","text":"airport","targetId":"word-airport","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-002-01"},{"type":"text","text":", at the "},{"type":"phrase","text":"grocery store","targetId":"phrase-grocery-store","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-002-02"},{"type":"text","text":", at the house, and in the kitchen."}]},{"en":"These are the words that native speakers use every day.","tc":"這些是母語人士每天使用的單詞。","englishTokens":[{"type":"text","text":"These are the words that "},{"type":"word","text":"native","targetId":"word-native","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-003-01"},{"type":"text","text":" speakers use every day."}]},{"en":"Listen, repeat, and see how many you already know.","tc":"聽，重複，看看你已經知道了多少。","englishTokens":[{"type":"text","text":"Listen, repeat, and see how many you already know."}]}],"tags":[]},{"id":"scene-02","no":"02","titleZh":"第 2 段","titleEn":"Part 2","sentences":[{"en":"Enjoy.","tc":"享受吧。","englishTokens":[{"type":"text","text":"Enjoy."}]},{"en":"Today I want to talk about grocery stores and supermarkets.","tc":"今天我想談談雜貨店和超市。","englishTokens":[{"type":"text","text":"Today I want to talk about "},{"type":"word","text":"grocery","targetId":"word-grocery","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-006-01"},{"type":"text","text":" stores and "},{"type":"word","text":"supermarkets","targetId":"word-supermarket","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-006-02"},{"type":"text","text":"."}]},{"en":"How to use essential words when going to the grocery store.","tc":"去雜貨店时如何使用基本詞彙。","englishTokens":[{"type":"text","text":"How to use "},{"type":"word","text":"essential","targetId":"word-essential","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-02-003-001"},{"type":"text","text":" words when going to the "},{"type":"phrase","text":"grocery store","targetId":"phrase-grocery-store","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-02-003-002"},{"type":"text","text":"."}]},{"en":"Some essential phrases, questions, and vocabulary, all in a slow, comprehensible way.","tc":"一些基本短語、問题和詞彙，全部以缓慢且易于理解的方式进行。","englishTokens":[{"type":"text","text":"Some essential "},{"type":"word","text":"phrases","targetId":"word-phrase","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-008-01"},{"type":"text","text":", questions, and vocabulary, all in a slow, "},{"type":"word","text":"comprehensible","targetId":"word-comprehensible","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-008-02"},{"type":"text","text":" way."}]}],"tags":[]},{"id":"scene-03","no":"03","titleZh":"第 3 段","titleEn":"Part 3","sentences":[{"en":"I love grocery stores.","tc":"我喜歡雜貨店。","englishTokens":[{"type":"text","text":"I love "},{"type":"word","text":"grocery","targetId":"word-grocery","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-03-001-001"},{"type":"text","text":" stores."}]},{"en":"I love grocery stores like Walmart, Costco, Sam's, and Target.","tc":"我喜歡沃尔玛、好市多、山姆和塔吉特等雜貨店。","englishTokens":[{"type":"text","text":"I love "},{"type":"word","text":"grocery","targetId":"word-grocery","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-03-002-001"},{"type":"text","text":" stores like Walmart, Costco, Sam's, and Target."}]},{"en":"Those are my favorite stores for groceries.","tc":"這些是我最喜歡的雜貨店。","englishTokens":[{"type":"text","text":"Those are my favorite stores for groceries."}]},{"en":"I like those stores the most because I love trying samples of different food in the store.","tc":"我最喜歡那些商店，因為我喜歡在店里嘗試不同的食物樣品。","englishTokens":[{"type":"text","text":"I like those stores the most because I love trying samples of different food in the store."}]}],"tags":[]},{"id":"scene-04","no":"04","titleZh":"第 4 段","titleEn":"Part 4","sentences":[{"en":"And in those grocery stores, they always have free samples with no cost.","tc":"在那些雜貨店里，他們總是免費提供免費樣品。","englishTokens":[{"type":"text","text":"And in those grocery stores, they always "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-013-01"},{"type":"text","text":" free samples with no cost."}]},{"en":"Free.","tc":"免費。","englishTokens":[{"type":"text","text":"Free."}]},{"en":"I also love these stores because the aisles are so wide.","tc":"我也喜歡這些商店，因為過道很寬。","englishTokens":[{"type":"text","text":"I also love these stores because the aisles are so wide."}]},{"en":"Not narrow, but the aisles are wide.","tc":"不窄，但過道很寬。","englishTokens":[{"type":"text","text":"Not narrow, but the aisles are wide."}]}],"tags":[]},{"id":"scene-05","no":"05","titleZh":"第 5 段","titleEn":"Part 5","sentences":[{"en":"At some stores like Bodega, Soriana, the aisles are too narrow.","tc":"在Bodega、Soriana等一些商店，過道太窄。","englishTokens":[{"type":"text","text":"At some stores like Bodega, Soriana, the aisles are too narrow."}]},{"en":"That's why I prefer places like Walmart with wide aisles.","tc":"這就是為什麼我更喜歡像沃尔玛這樣通道寬阔的地方。","englishTokens":[{"type":"text","text":"That's why I prefer places like Walmart with wide aisles."}]},{"en":"My favorite aisle is the detergent aisle.","tc":"我最喜歡的通道是洗涤劑通道。","englishTokens":[{"type":"text","text":"My favorite aisle is the detergent aisle."}]},{"en":"It smells so good.","tc":"味道真好。","englishTokens":[{"type":"text","text":"It smells so good."}]}],"tags":[]},{"id":"scene-06","no":"06","titleZh":"第 6 段","titleEn":"Part 6","sentences":[{"en":"It smells so fresh and clean.","tc":"闻起來很清新、乾淨。","englishTokens":[{"type":"text","text":"It smells so fresh and clean."}]},{"en":"As a customer at Walmart, I always feel comfortable.","tc":"作為沃尔玛的顧客，我總是感覺很舒服。","englishTokens":[{"type":"text","text":"As a customer at Walmart, I always feel comfortable."}]},{"en":"The temperature is usually very cool and the shopping carts stroll really smooth down the aisles.","tc":"氣温通常非常凉爽，購物車在過道上行驶非常顺畅。","englishTokens":[{"type":"text","text":"The temperature is usually very cool and the shopping carts stroll really smooth down the aisles."}]},{"en":"I like to stroll around on them sometimes.","tc":"有时我喜歡在它們上面闲逛。","englishTokens":[{"type":"text","text":"I like to stroll around on them sometimes."}]}],"tags":[]},{"id":"scene-07","no":"07","titleZh":"第 7 段","titleEn":"Part 7","sentences":[{"en":"Sometimes I like to skate on them or lean on them.","tc":"有时我喜歡在它們上面滑冰或者靠在它們上面。","englishTokens":[{"type":"text","text":"Sometimes I like to skate on them or lean on them."}]},{"en":"What's your favorite grocery store to visit and why?","tc":"您最喜歡去哪家雜貨店？為什麼？","englishTokens":[{"type":"text","text":"What's your favorite "},{"type":"phrase","text":"grocery store","targetId":"phrase-grocery-store","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-07-002-001"},{"type":"text","text":" to visit and why?"}]},{"en":"What makes a grocery store feel comfy for you?","tc":"是什麼讓您對雜貨店感到舒适？","englishTokens":[{"type":"text","text":"What makes a "},{"type":"phrase","text":"grocery store","targetId":"phrase-grocery-store","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-07-003-001"},{"type":"text","text":" feel comfy for you?"}]},{"en":"The smells, the shopping carts, the people.","tc":"氣味、購物車、人。","englishTokens":[{"type":"text","text":"The smells, the shopping carts, the people."}]}],"tags":[]},{"id":"scene-08","no":"08","titleZh":"第 8 段","titleEn":"Part 8","sentences":[{"en":"When I'm ready to check out all of my groceries, I normally try to go to self checkout.","tc":"當我准備好结账所有雜貨时，我通常會嘗試自助结账。","englishTokens":[{"type":"text","text":"When I'm ready to check out all of my groceries, I normally try "},{"type":"phrase","text":"to go","targetId":"phrase-to-go","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-029-01"},{"type":"text","text":" to self checkout."}]},{"en":"The lines the queue is usually shorter than regular checkout.","tc":"排队的队伍通常比常规结账的队伍要短。","englishTokens":[{"type":"text","text":"The lines the queue is usually shorter than regular checkout."}]},{"en":"So self checkout is a lot faster and I always prefer to get my fresh produce like vegetables and fruits at the local market.","tc":"因此，自助结账速度要快得多，我總是更喜歡在當地市場購買蔬菜和水果等新鮮農产品。","englishTokens":[{"type":"text","text":"So self checkout is a lot faster and I always prefer to "},{"type":"usage","text":"get","targetId":"usage-get-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-031-01"},{"type":"text","text":" my fresh produce like vegetables and fruits at the local market."}]},{"en":"I prefer going to the local market for food that's fresh, fresh produce.","tc":"我更喜歡去當地市場購買新鮮的農产品。","englishTokens":[{"type":"text","text":"I prefer going to the local market for food that's fresh, fresh produce."}]}],"tags":[]},{"id":"scene-09","no":"09","titleZh":"第 9 段","titleEn":"Part 9","sentences":[{"en":"I usually need a whole bunch of bananas.","tc":"我通常需要一整串香蕉。","englishTokens":[{"type":"text","text":"I usually need a whole bunch of bananas."}]},{"en":"I eat one banana every day.","tc":"我每天吃一根香蕉。","englishTokens":[{"type":"text","text":"I eat one banana every day."}]},{"en":"So, I need at least five bananas for my week.","tc":"所以，我一周至少需要五個香蕉。","englishTokens":[{"type":"text","text":"So, I need at least five bananas for my week."}]},{"en":"1 kilo of bananas is usually enough for me.","tc":"1公斤香蕉通常對我來說就足夠了。","englishTokens":[{"type":"text","text":"1 kilo of bananas is usually enough for me."}]}],"tags":[]},{"id":"scene-10","no":"10","titleZh":"第 10 段","titleEn":"Part 10","sentences":[{"en":"It's usually a whole bunch of bananas.","tc":"通常是一整串香蕉。","englishTokens":[{"type":"text","text":"It's usually a whole bunch of bananas."}]},{"en":"How many kilos of bananas do you normally buy per week from Sunday to Saturday?","tc":"从周日到周六，您通常每周購買多少公斤香蕉？","englishTokens":[{"type":"text","text":"How many kilos of bananas do you normally buy per week from Sunday to Saturday?"}]},{"en":"How many do you buy?","tc":"你買了多少？","englishTokens":[{"type":"text","text":"How many do you buy?"}]},{"en":"I don't like going to big chain supermarkets to buy fresh produce.","tc":"我不喜歡去大型连锁超市購買生鮮農产品。","englishTokens":[{"type":"text","text":"I don't like going to big chain "},{"type":"word","text":"supermarkets","targetId":"word-supermarket","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-10-004-001"},{"type":"text","text":" to buy fresh produce."}]}],"tags":[]},{"id":"scene-11","no":"11","titleZh":"第 11 段","titleEn":"Part 11","sentences":[{"en":"However, when it comes to meat like beef, chicken, pork, or fish, I prefer to go to a big chain supermarket.","tc":"然而，當談到牛肉、雞肉、猪肉或魚等肉类时，我更喜歡去大型连锁超市。","englishTokens":[{"type":"text","text":"However, when it comes to meat like beef, chicken, pork, or fish, I prefer "},{"type":"phrase","text":"to go","targetId":"phrase-to-go","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-11-001-001"},{"type":"text","text":" to a big chain "},{"type":"word","text":"supermarket","targetId":"word-supermarket","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-11-001-002"},{"type":"text","text":"."}]},{"en":"I get nervous buying at outdoor markets.","tc":"我在户外市場購買时感到緊張。","englishTokens":[{"type":"text","text":"I "},{"type":"usage","text":"get","targetId":"usage-get-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-11-002-001"},{"type":"text","text":" nervous buying at outdoor markets."}]},{"en":"The meat sometimes sits in the sun all day.","tc":"肉有时整天放在陽光下。","englishTokens":[{"type":"text","text":"The meat sometimes sits in the sun all day."}]},{"en":"The same with dairy products.","tc":"乳制品也是如此。","englishTokens":[{"type":"text","text":"The same with dairy products."}]}],"tags":[]},{"id":"scene-12","no":"12","titleZh":"第 12 段","titleEn":"Part 12","sentences":[{"en":"I prefer to go to a big chain supermarket for my dairy products.","tc":"我更喜歡去大型连锁超市購買乳制品。","englishTokens":[{"type":"text","text":"I prefer "},{"type":"phrase","text":"to go","targetId":"phrase-to-go","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-12-001-001"},{"type":"text","text":" to a big chain "},{"type":"word","text":"supermarket","targetId":"word-supermarket","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-12-001-002"},{"type":"text","text":" for my dairy products."}]},{"en":"And I really like walking down the aisle at places like Walmart or Soriana to buy my dairy products.","tc":"我真的很喜歡沿着沃尔玛或Soriana等地方的過道購買乳制品。","englishTokens":[{"type":"text","text":"And I really like walking down the aisle at places like Walmart or Soriana to buy my dairy products."}]},{"en":"I just love dairy products.","tc":"我就是喜歡乳制品。","englishTokens":[{"type":"text","text":"I just love dairy products."}]},{"en":"Cottage cheese, Greek yogurt, ice cream.","tc":"白乾酪、希腊酸奶、冰淇淋。","englishTokens":[{"type":"text","text":"Cottage cheese, Greek yogurt, ice cream."}]}],"tags":[]},{"id":"scene-13","no":"13","titleZh":"第 13 段","titleEn":"Part 13","sentences":[{"en":"I love it all.","tc":"我喜歡這一切。","englishTokens":[{"type":"text","text":"I love it all."}]},{"en":"But I am lactose intolerant.","tc":"但我有乳糖不耐症。","englishTokens":[{"type":"text","text":"But I am lactose intolerant."}]},{"en":"So dairy products make me feel very sick.","tc":"所以乳制品讓我感覺很惡心。","englishTokens":[{"type":"text","text":"So dairy products "},{"type":"usage","text":"make","targetId":"usage-make-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-051-01"},{"type":"text","text":" me feel very sick."}]},{"en":"But I don't care.","tc":"但我不在乎。","englishTokens":[{"type":"text","text":"But I don't care."}]}],"tags":[]},{"id":"scene-14","no":"14","titleZh":"第 14 段","titleEn":"Part 14","sentences":[{"en":"I get sick and I don't care.","tc":"我生病了，我不在乎。","englishTokens":[{"type":"text","text":"I "},{"type":"usage","text":"get","targetId":"usage-get-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-14-001-001"},{"type":"text","text":" sick and I don't care."}]},{"en":"I love dairy products.","tc":"我喜歡乳制品。","englishTokens":[{"type":"text","text":"I love dairy products."}]},{"en":"Now, when it comes to dairy products like eggs, I don't really like eggs.","tc":"現在，說到雞蛋等乳制品，我不太喜歡雞蛋。","englishTokens":[{"type":"text","text":"Now, when it comes to dairy products like eggs, I don't really like eggs."}]},{"en":"I can never buy a dozen eggs.","tc":"我永遠買不到一打雞蛋。","englishTokens":[{"type":"text","text":"I can never buy a dozen eggs."}]}],"tags":[]},{"id":"scene-15","no":"15","titleZh":"第 15 段","titleEn":"Part 15","sentences":[{"en":"A dozen is 12 eggs.","tc":"一打是12個雞蛋。","englishTokens":[{"type":"text","text":"A dozen is 12 eggs."}]},{"en":"It's too much for me.","tc":"這對我來說太過分了。","englishTokens":[{"type":"text","text":"It's too much for me."}]},{"en":"If I'm with my family though, we will get a dozen eggs.","tc":"如果我和家人在一起，我們會得到一打雞蛋。","englishTokens":[{"type":"text","text":"If I'm with my family though, we will "},{"type":"usage","text":"get","targetId":"usage-get-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-15-003-001"},{"type":"text","text":" a dozen eggs."}]},{"en":"Can you finish a dozen eggs all by yourself?","tc":"你一個人能吃完一打雞蛋嗎？","englishTokens":[{"type":"text","text":"Can you finish a dozen eggs all by yourself?"}]}],"tags":[]},{"id":"scene-16","no":"16","titleZh":"第 16 段","titleEn":"Part 16","sentences":[{"en":"Now, when it comes to buying pastries or bread, I always go to the local bakery.","tc":"現在，當談到購買糕点或面包时，我總是去當地的面包店。","englishTokens":[{"type":"text","text":"Now, when it comes to buying pastries or bread, I always go to the local bakery."}]},{"en":"Bakeries, in my opinion, are the only way to buy bread.","tc":"在我看來，面包店是購買面包的唯一途径。","englishTokens":[{"type":"text","text":"Bakeries, in my opinion, are the only way to buy bread."}]},{"en":"Bread has to be made with love.","tc":"面包必須用愛來制作。","englishTokens":[{"type":"text","text":"Bread has to be made with love."}]},{"en":"My friend once told me that bread doesn't go to your stomach.","tc":"我的朋友曾經告诉我，面包不會进入你的胃。","englishTokens":[{"type":"text","text":"My friend once told me that bread doesn't go to your stomach."}]}],"tags":[]},{"id":"scene-17","no":"17","titleZh":"第 17 段","titleEn":"Part 17","sentences":[{"en":"Bread goes to your heart.","tc":"面包會送到你的心里。","englishTokens":[{"type":"text","text":"Bread goes to your heart."}]},{"en":"And you can taste the love put into bread, I think.","tc":"我想，你可以嘗到面包中的愛。","englishTokens":[{"type":"text","text":"And you can taste the love put into bread, I think."}]},{"en":"And the freshly homemade flavor is incomparable.","tc":"而且新鮮的自制风味是無與伦比的。","englishTokens":[{"type":"text","text":"And the freshly homemade flavor is incomparable."}]},{"en":"What do you think?","tc":"你覺得呢？","englishTokens":[{"type":"text","text":"What do you think?"}]}],"tags":[]},{"id":"scene-18","no":"18","titleZh":"第 18 段","titleEn":"Part 18","sentences":[{"en":"What's your favorite food aisle?","tc":"你最喜歡哪個食品通道？","englishTokens":[{"type":"text","text":"What's your favorite food aisle?"}]},{"en":"The dairy aisle.","tc":"乳制品過道。","englishTokens":[{"type":"text","text":"The dairy aisle."}]},{"en":"Drinks, snacks, canned goods, condiments like ketchup, mayo, mustard.","tc":"飲料、零食、罐頭食品、番茄醬、蛋黄醬、芥末等调味品。","englishTokens":[{"type":"text","text":"Drinks, snacks, canned goods, condiments like ketchup, mayo, mustard."}]},{"en":"The prices at each grocery store make a big difference when you're buying in bulk.","tc":"當您批量購買时，每個雜貨店的價格會有很大差异。","englishTokens":[{"type":"text","text":"The prices at each "},{"type":"phrase","text":"grocery store","targetId":"phrase-grocery-store","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-18-004-001"},{"type":"text","text":" "},{"type":"usage","text":"make","targetId":"usage-make-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-18-004-002"},{"type":"text","text":" a big difference when you're buying in bulk."}]}],"tags":[]},{"id":"scene-19","no":"19","titleZh":"第 19 段","titleEn":"Part 19","sentences":[{"en":"Lots of people prefer to buy things that will last a long time.","tc":"很多人喜歡購買可以使用很長时間的东西。","englishTokens":[{"type":"text","text":"Lots of people prefer to buy things that will last a long time."}]},{"en":"And places like Walmart or Costco are usually more expensive than places like Aurora or Soirana.","tc":"像沃尔玛或Costco這樣的地方通常比Aurora或Soirana這樣的地方更貴。","englishTokens":[{"type":"text","text":"And places like Walmart or Costco are usually more expensive than places like Aurora or Soirana."}]},{"en":"Less international big chain stores.","tc":"國際大型连锁店较少。","englishTokens":[{"type":"text","text":"Less international big chain stores."}]},{"en":"They usually have more sales and discounts.","tc":"他們通常有更多的销售和折扣。","englishTokens":[{"type":"text","text":"They usually "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-19-004-001"},{"type":"text","text":" more sales and discounts."}]}],"tags":[]},{"id":"scene-20","no":"20","titleZh":"第 20 段","titleEn":"Part 20","sentences":[{"en":"I like buying expensive things for cheap prices.","tc":"我喜歡以便宜的價格購買昂貴的东西。","englishTokens":[{"type":"text","text":"I like buying expensive things for cheap prices."}]},{"en":"When I go to the checkout to pay for my groceries, I normally use my credit card because I never have coins or change or even bills with me.","tc":"當我去收银台支付雜貨費用时，我通常使用信用卡，因為我身上从來沒有硬币、零錢甚至账單。","englishTokens":[{"type":"text","text":"When I go to the checkout to pay for my groceries, I normally use my credit card because I never "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-20-002-001"},{"type":"text","text":" coins or change or even bills with me."}]},{"en":"So, in conclusion, even though the big chain supermarkets are more convenient because of the shopping carts, the credit card payments, and the big aisles,.","tc":"所以，總而言之，尽管大型连锁超市因為購物車、信用卡支付和大通道而更方便。","englishTokens":[{"type":"text","text":"So, in conclusion, even though the big chain "},{"type":"word","text":"supermarkets","targetId":"word-supermarket","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-20-003-001"},{"type":"text","text":" are more convenient because of the shopping carts, the credit card payments, and the big aisles,."}]},{"en":"I still always prefer going to local supermarkets to support the community.","tc":"我仍然更喜歡去當地的超市來支持社區。","englishTokens":[{"type":"text","text":"I still always prefer going to local "},{"type":"word","text":"supermarkets","targetId":"word-supermarket","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-20-004-001"},{"type":"text","text":" to support the community."}]}],"tags":[]},{"id":"scene-21","no":"21","titleZh":"第 21 段","titleEn":"Part 21","sentences":[{"en":"What do you prefer?","tc":"你更喜歡什麼？","englishTokens":[{"type":"text","text":"What do you prefer?"}]},{"en":"Big chain grocery stores or local supermarkets?","tc":"大型连锁雜貨店还是當地超市？","englishTokens":[{"type":"text","text":"Big chain "},{"type":"word","text":"grocery","targetId":"word-grocery","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-21-002-001"},{"type":"text","text":" stores or local "},{"type":"word","text":"supermarkets","targetId":"word-supermarket","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-21-002-002"},{"type":"text","text":"?"}]},{"en":"Now for a little challenge question.","tc":"現在有一個小挑战問题。","englishTokens":[{"type":"text","text":"Now for a little "},{"type":"word","text":"challenge","targetId":"word-challenge","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-083-01"},{"type":"text","text":" question."}]},{"en":"Tell me what is the difference between a bag, a box, a can, a jar, a bottle, a carton, and a package.","tc":"告诉我袋子、盒子、罐子、罐子、瓶子、纸箱和包装有什麼區別。","englishTokens":[{"type":"text","text":"Tell me what is the difference between a bag, a box, a can, a jar, a bottle, a carton, and a package."}]}],"tags":[]},{"id":"scene-22","no":"22","titleZh":"第 22 段","titleEn":"Part 22","sentences":[{"en":"Tell me one thing you can find in each packaging.","tc":"告诉我您可以在每個包装中找到的一件事。","englishTokens":[{"type":"text","text":"Tell me one thing you can find in each packaging."}]},{"en":"For example, I can find milk or juice in a carton.","tc":"例如，我可以在纸盒中找到牛奶或果汁。","englishTokens":[{"type":"text","text":"For example, I can find milk or juice in a carton."}]},{"en":"I can find jelly or olives in a jar.","tc":"我可以在罐子里找到果冻或橄榄。","englishTokens":[{"type":"text","text":"I can find jelly or olives in a jar."}]},{"en":"Also remember to use some useful phrases at the supermarket or grocery store.","tc":"还要记住在超市或雜貨店使用一些有用的短語。","englishTokens":[{"type":"text","text":"Also remember to use some useful "},{"type":"word","text":"phrases","targetId":"word-phrase","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-22-004-001"},{"type":"text","text":" at the "},{"type":"word","text":"supermarket","targetId":"word-supermarket","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-22-004-002"},{"type":"text","text":" or "},{"type":"phrase","text":"grocery store","targetId":"phrase-grocery-store","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-22-004-003"},{"type":"text","text":"."}]}],"tags":[]},{"id":"scene-23","no":"23","titleZh":"第 23 段","titleEn":"Part 23","sentences":[{"en":"If you're looking for something and you can't find it, you could say, \\"Where can I find the milk?\\"","tc":"如果你正在尋找某樣东西但找不到，你可以說：“我在哪里可以找到牛奶？”。","englishTokens":[{"type":"text","text":"If you're looking for something and you can't find it, you could say, \\"Where can I find the milk?\\""}]},{"en":"I'm looking for the milk.","tc":"我在找牛奶。","englishTokens":[{"type":"text","text":"I'm looking for the milk."}]},{"en":"Do you have any milk?","tc":"有牛奶嗎？","englishTokens":[{"type":"text","text":"Do you "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-23-003-001"},{"type":"text","text":" any milk?"}]},{"en":"Or to ask the price of something, you can say, \\"How much does this cost?\\"","tc":"或者询問某物的價格，你可以說“Howmuchdoesthiscost?”。","englishTokens":[{"type":"text","text":"Or to ask the price of something, you can say, \\"How much does this cost?\\""}]}],"tags":[]},{"id":"scene-24","no":"24","titleZh":"第 24 段","titleEn":"Part 24","sentences":[{"en":"\\"How much does this cost?\\"","tc":"“這個要多少錢？”。","englishTokens":[{"type":"text","text":"\\"How much does this cost?\\""}]},{"en":"And when making a card payment, you can ask, \\"Can I pay by card or can I pay with cash?\\"","tc":"并且在进行卡支付时，您​​可以询問“我可以用卡支付还是可以用現金支付？”。","englishTokens":[{"type":"text","text":"And when making a card payment, you can ask, \\"Can I pay by card or can I pay with cash?\\""}]},{"en":"It depends if you're using cash or card.","tc":"這取決于您使用的是現金还是银行卡。","englishTokens":[{"type":"text","text":"It depends if you're using cash or card."}]},{"en":"They might ask you paper or plastic or would you like a receipt?","tc":"他們可能會問您纸質还是塑料，或者您想要收據嗎？","englishTokens":[{"type":"text","text":"They might ask you paper or plastic or would you like a receipt?"}]}],"tags":[]},{"id":"scene-25","no":"25","titleZh":"第 25 段","titleEn":"Part 25","sentences":[{"en":"I hope these phrases helped you.","tc":"希望這些短語對您有所幫助。","englishTokens":[{"type":"text","text":"I hope these "},{"type":"word","text":"phrases","targetId":"word-phrase","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-25-001-001"},{"type":"text","text":" helped you."}]},{"en":"And I hope you remember some of these in the future when you go grocery shopping.","tc":"我希望你将來去雜貨店購物时记住其中一些。","englishTokens":[{"type":"text","text":"And I hope you remember some of these in the future when you go "},{"type":"word","text":"grocery","targetId":"word-grocery","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-25-002-001"},{"type":"text","text":" shopping."}]},{"en":"I am just coming back from the grocery store.","tc":"我剛从雜貨店回來。","englishTokens":[{"type":"text","text":"I am just coming back from the "},{"type":"phrase","text":"grocery store","targetId":"phrase-grocery-store","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-25-003-001"},{"type":"text","text":"."}]},{"en":"Today has been a super busy day.","tc":"今天真是超级忙碌的一天。","englishTokens":[{"type":"text","text":"Today has been a super busy day."}]}],"tags":[]},{"id":"scene-26","no":"26","titleZh":"第 26 段","titleEn":"Part 26","sentences":[{"en":"I am renting a new apartment, and it needs all of the essential things that we often forget.","tc":"我正在租一套新公寓，它需要我們經常忘记的所有必需品。","englishTokens":[{"type":"text","text":"I am renting a new apartment, and it needs all of the "},{"type":"word","text":"essential","targetId":"word-essential","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-26-001-001"},{"type":"text","text":" things that we often forget."}]},{"en":"So, I did some grocery shopping with the essentials that my kitchen needs first.","tc":"所以，我先去雜貨店買了廚房需要的必需品。","englishTokens":[{"type":"text","text":"So, I did some "},{"type":"word","text":"grocery","targetId":"word-grocery","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-26-002-001"},{"type":"text","text":" shopping with the essentials that my kitchen needs first."}]},{"en":"I moved in this morning and my room is almost finished.","tc":"我今天早上搬进來，我的房間快完工了。","englishTokens":[{"type":"text","text":"I moved in this morning and my room is almost finished."}]},{"en":"I already bought a mattress, a chair, and a desk for my room.","tc":"我已經為我的房間買了床墊、椅子和桌子。","englishTokens":[{"type":"text","text":"I already bought a mattress, a chair, and a desk for my room."}]}],"tags":[]},{"id":"scene-27","no":"27","titleZh":"第 27 段","titleEn":"Part 27","sentences":[{"en":"The most important parts done.","tc":"完成的最重要的部分。","englishTokens":[{"type":"text","text":"The most important parts done."}]},{"en":"But then I realized I can't eat or cook anything.","tc":"但後來我意識到我不能吃或煮任何东西。","englishTokens":[{"type":"text","text":"But then I realized I can't eat or cook anything."}]},{"en":"I need to go to the store again and buy some kitchen essentials.","tc":"我需要再次去商店購買一些廚房必需品。","englishTokens":[{"type":"text","text":"I need "},{"type":"phrase","text":"to go","targetId":"phrase-to-go","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-27-003-001"},{"type":"text","text":" to the store again and buy some kitchen essentials."}]},{"en":"I don't have a car and even if I did, I don't know how to drive.","tc":"我沒有車，即使有，我也不知道怎麼開車。","englishTokens":[{"type":"text","text":"I don't "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-27-004-001"},{"type":"text","text":" a car and even if I did, I don't know how to drive."}]}],"tags":[]},{"id":"scene-28","no":"28","titleZh":"第 28 段","titleEn":"Part 28","sentences":[{"en":"I know.","tc":"我知道。","englishTokens":[{"type":"text","text":"I know."}]},{"en":"Everybody is so shocked when I tell them I can't drive.","tc":"當我告诉他們我不會開車时，每個人都感到非常震惊。","englishTokens":[{"type":"text","text":"Everybody is so shocked when I tell them I can't drive."}]},{"en":"But in Mexico, I just never found it very necessary.","tc":"但在墨西哥，我从來沒有發現它非常必要。","englishTokens":[{"type":"text","text":"But in Mexico, I just never found it very necessary."}]},{"en":"There's public transportation to get anywhere, and it's much cheaper and much faster.","tc":"有公共交通可以到達任何地方，而且更便宜、更快。","englishTokens":[{"type":"text","text":"There's public "},{"type":"word","text":"transportation","targetId":"word-transportation","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-112-01"},{"type":"text","text":" to get anywhere, and it's much cheaper and much faster."}]}],"tags":[]},{"id":"scene-29","no":"29","titleZh":"第 29 段","titleEn":"Part 29","sentences":[{"en":"Here's my receipt.","tc":"這是我的收據。","englishTokens":[{"type":"text","text":"Here's my receipt."}]},{"en":"I spent 614 Mexican pesos on all of this.","tc":"我在這一切上花了614墨西哥比索。","englishTokens":[{"type":"text","text":"I spent 614 Mexican pesos on all of this."}]},{"en":"So, I had to walk to Bodega Ara.","tc":"所以，我不得不步行去BodegaAra。","englishTokens":[{"type":"text","text":"So, I had to walk to Bodega Ara."}]},{"en":"It's a grocery store in Mexico.","tc":"這是墨西哥的一家雜貨店。","englishTokens":[{"type":"text","text":"It's a "},{"type":"phrase","text":"grocery store","targetId":"phrase-grocery-store","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-29-004-001"},{"type":"text","text":" in Mexico."}]}],"tags":[]},{"id":"scene-30","no":"30","titleZh":"第 30 段","titleEn":"Part 30","sentences":[{"en":"I have my tote bag.","tc":"我有我的手提包。","englishTokens":[{"type":"text","text":"I "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-30-001-001"},{"type":"text","text":" my tote bag."}]},{"en":"Since I walked, I could only fill one tote bag of groceries and essentials.","tc":"由于我步行，我只能装滿一手提袋的雜貨和必需品。","englishTokens":[{"type":"text","text":"Since I walked, I could only fill one tote bag of groceries and essentials."}]},{"en":"I got one bowl.","tc":"我有一碗。","englishTokens":[{"type":"text","text":"I got one bowl."}]},{"en":"Very important.","tc":"非常重要。","englishTokens":[{"type":"text","text":"Very important."}]}],"tags":[]},{"id":"scene-31","no":"31","titleZh":"第 31 段","titleEn":"Part 31","sentences":[{"en":"I bought a kitchen towel.","tc":"我買了一条廚房毛巾。","englishTokens":[{"type":"text","text":"I bought a kitchen towel."}]},{"en":"I'm going to need this to dry the dishes, dry my hands, wipe the table to dry my dishes on since I don't have a dish rack yet.","tc":"因為我还沒有碗碟架，所以我需要它來擦乾碗碟、擦乾我的手、擦桌子來擦乾我的碗碟。","englishTokens":[{"type":"text","text":"I'm going to need this to dry the dishes, dry my hands, wipe the table to dry my dishes on since I don't "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-31-002-001"},{"type":"text","text":" a dish rack yet."}]},{"en":"I got a bowl, of course.","tc":"當然，我有一個碗。","englishTokens":[{"type":"text","text":"I got a bowl, of course."}]},{"en":"I love wooden bowls.","tc":"我喜歡木碗。","englishTokens":[{"type":"text","text":"I love wooden bowls."}]}],"tags":[]},{"id":"scene-32","no":"32","titleZh":"第 32 段","titleEn":"Part 32","sentences":[{"en":"No microplastics.","tc":"不含微塑料。","englishTokens":[{"type":"text","text":"No microplastics."}]},{"en":"Then a glass black bowl.","tc":"然後是一個黑色玻璃碗。","englishTokens":[{"type":"text","text":"Then a glass black bowl."}]},{"en":"I love black dishes.","tc":"我喜歡黑色的菜肴。","englishTokens":[{"type":"text","text":"I love black dishes."}]},{"en":"And to match a black mug for my smoothies because I don't drink coffee.","tc":"并為我的冰沙搭配黑色杯子，因為我不喝咖啡。","englishTokens":[{"type":"text","text":"And to match a black mug for my smoothies because I don't drink coffee."}]}],"tags":[]},{"id":"scene-33","no":"33","titleZh":"第 33 段","titleEn":"Part 33","sentences":[{"en":"A pan which I think will come in handy when I want to cook rice or pasta or soup.","tc":"我認為當我想煮米飯、面食或汤时會派上用場的平底鍋。","englishTokens":[{"type":"text","text":"A pan which I think will come in handy when I want to cook rice or pasta or soup."}]},{"en":"Anything can really be cooked in this pan.","tc":"這個鍋真的可以煮任何东西。","englishTokens":[{"type":"text","text":"Anything can really be cooked in this pan."}]},{"en":"It's wide enough and deep enough.","tc":"足夠寬、足夠深。","englishTokens":[{"type":"text","text":"It's wide enough and deep enough."}]},{"en":"Wide and deep.","tc":"寬而深。","englishTokens":[{"type":"text","text":"Wide and deep."}]}],"tags":[]},{"id":"scene-34","no":"34","titleZh":"第 34 段","titleEn":"Part 34","sentences":[{"en":"To come in handy is an expression we use when we mean something will be useful to us in the future.","tc":"當我們表示某些东西将來對我們有用时，我們會使用“Careinhandy”這個表達方式。","englishTokens":[{"type":"text","text":"To come in handy is an expression we use when we mean something will be useful to us in the future."}]},{"en":"I got dish soap.","tc":"我有洗潔精。","englishTokens":[{"type":"text","text":"I got dish soap."}]},{"en":"I almost forgot about this one.","tc":"我差点忘了這個。","englishTokens":[{"type":"text","text":"I almost forgot about this one."}]},{"en":"It's so important.","tc":"這非常重要。","englishTokens":[{"type":"text","text":"It's so important."}]}],"tags":[]},{"id":"scene-35","no":"35","titleZh":"第 35 段","titleEn":"Part 35","sentences":[{"en":"But I feel like you don't really think about it.","tc":"但我覺得你并沒有真正考慮過這一点。","englishTokens":[{"type":"text","text":"But I feel like you don't really think about it."}]},{"en":"You think about your couch, your fridge, your bed, your desk, your TV, your dishes.","tc":"你會想到你的沙發、你的冰箱、你的床、你的桌子、你的電視、你的盤子。","englishTokens":[{"type":"text","text":"You think about your couch, your fridge, your bed, your desk, your TV, your dishes."}]},{"en":"But you don't think about your broom, your sponge, your dish soap, your trash can.","tc":"但你不會想到你的扫帚、你的海绵、你的洗潔精、你的垃圾桶。","englishTokens":[{"type":"text","text":"But you don't think about your broom, your sponge, your dish soap, your trash can."}]},{"en":"They're super important, but we seem to forget about them because I think they're a little bit boring, but nevertheless, very important.","tc":"它們非常重要，但我們似乎忘记了它們，因為我認為它們有点無聊，但仍然非常重要。","englishTokens":[{"type":"text","text":"They're super important, but we seem to forget about them because I think they're a little bit boring, but nevertheless, very important."}]}],"tags":[]},{"id":"scene-36","no":"36","titleZh":"第 36 段","titleEn":"Part 36","sentences":[{"en":"Definitely a kitchen essential.","tc":"绝對是廚房必備品。","englishTokens":[{"type":"text","text":"Definitely a kitchen "},{"type":"word","text":"essential","targetId":"word-essential","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-36-001-001"},{"type":"text","text":"."}]},{"en":"Of course, I couldn't forget my sponge and a potato peeler.","tc":"當然，我不能忘记我的海绵和土豆削皮器。","englishTokens":[{"type":"text","text":"Of course, I couldn't forget my sponge and a potato peeler."}]},{"en":"We call this a potato peeler because it peels potatoes.","tc":"我們称其為土豆削皮器，因為它可以削土豆皮。","englishTokens":[{"type":"text","text":"We call this a potato peeler because it peels potatoes."}]},{"en":"You can also peel carrots or apples.","tc":"您也可以削胡蘿卜或蘋果皮。","englishTokens":[{"type":"text","text":"You can also peel carrots or apples."}]}],"tags":[]},{"id":"scene-37","no":"37","titleZh":"第 37 段","titleEn":"Part 37","sentences":[{"en":"Let me know in the comments what else can you peel.","tc":"在评论中讓我知道你还能剥什麼。","englishTokens":[{"type":"text","text":"Let me know in the comments what else can you peel."}]},{"en":"I also bought a knife and I bought a broom.","tc":"我还買了一把刀，我買了一把扫帚。","englishTokens":[{"type":"text","text":"I also bought a knife and I bought a broom."}]},{"en":"As I was walking home, I realized I forgot to buy a dust pan.","tc":"當我走回家时，我意識到我忘记買簸箕了。","englishTokens":[{"type":"text","text":"As I was walking home, I realized I forgot to buy a dust pan."}]},{"en":"Also, something that you easily forget because it's a little bit boring.","tc":"另外，有些东西你很容易忘记，因為它有点無聊。","englishTokens":[{"type":"text","text":"Also, something that you easily forget because it's a little bit boring."}]}],"tags":[]},{"id":"scene-38","no":"38","titleZh":"第 38 段","titleEn":"Part 38","sentences":[{"en":"I also got a strainer.","tc":"我还有一個過滤器。","englishTokens":[{"type":"text","text":"I also got a strainer."}]},{"en":"This is super important for me because I drink kefir every day.","tc":"這對我來說非常重要，因為我每天都喝開菲尔。","englishTokens":[{"type":"text","text":"This is super important for me because I drink kefir every day."}]},{"en":"This is kefir.","tc":"這是開菲尔。","englishTokens":[{"type":"text","text":"This is kefir."}]},{"en":"Do you know what kefir is?","tc":"你知道開菲尔是什麼嗎？","englishTokens":[{"type":"text","text":"Do you know what kefir is?"}]}],"tags":[]},{"id":"scene-39","no":"39","titleZh":"第 39 段","titleEn":"Part 39","sentences":[{"en":"Let me know in the comments.","tc":"請在评论中告诉我。","englishTokens":[{"type":"text","text":"Let me know in the comments."}]},{"en":"I bought chopsticks.","tc":"我買了筷子。","englishTokens":[{"type":"text","text":"I bought chopsticks."}]},{"en":"These are all from my trip to Thailand.","tc":"這些都是我去泰國的旅行。","englishTokens":[{"type":"text","text":"These are all from my trip to Thailand."}]},{"en":"In Thailand, I bought so many wooden utensils.","tc":"在泰國，我買了很多木制器皿。","englishTokens":[{"type":"text","text":"In Thailand, I bought so many wooden utensils."}]}],"tags":[]},{"id":"scene-40","no":"40","titleZh":"第 40 段","titleEn":"Part 40","sentences":[{"en":"Wooden spoons.","tc":"木勺。","englishTokens":[{"type":"text","text":"Wooden spoons."}]},{"en":"Wooden little spoons.","tc":"木制小勺子。","englishTokens":[{"type":"text","text":"Wooden little spoons."}]},{"en":"I don't know what these are for, but they were cute.","tc":"我不知道這些是做什麼用的，但它們很可愛。","englishTokens":[{"type":"text","text":"I don't know what these are for, but they were cute."}]},{"en":"Wooden forks and more wooden spoons.","tc":"木叉和更多木勺。","englishTokens":[{"type":"text","text":"Wooden forks and more wooden spoons."}]}],"tags":[]},{"id":"scene-41","no":"41","titleZh":"第 41 段","titleEn":"Part 41","sentences":[{"en":"I also brought along my coconut oil.","tc":"我还帶了椰子油。","englishTokens":[{"type":"text","text":"I also brought along my coconut oil."}]},{"en":"You use it to cook food.","tc":"你用它來烹饪食物。","englishTokens":[{"type":"text","text":"You use it to cook food."}]},{"en":"And in my cupboards, I keep a glass of honey.","tc":"在我的橱櫃里，我放着一杯蜂蜜。","englishTokens":[{"type":"text","text":"And in my cupboards, I keep a glass of honey."}]},{"en":"I love honey.","tc":"我愛蜂蜜。","englishTokens":[{"type":"text","text":"I love honey."}]}],"tags":[]},{"id":"scene-42","no":"42","titleZh":"第 42 段","titleEn":"Part 42","sentences":[{"en":"Now, some unrelated things I bought today.","tc":"現在，我今天買了一些不相關的东西。","englishTokens":[{"type":"text","text":"Now, some unrelated things I bought today."}]},{"en":"Some hangers.","tc":"一些衣架。","englishTokens":[{"type":"text","text":"Some hangers."}]},{"en":"That's also something I think you don't realize you need until you're in a new apartment.","tc":"我認為這也是您在搬进新公寓之前不會意識到自己需要的东西。","englishTokens":[{"type":"text","text":"That's also something I think you don't realize you need until you're in a new apartment."}]},{"en":"What is one thing that you always forget about?","tc":"你總是忘记的一件事是什麼？","englishTokens":[{"type":"text","text":"What is one thing that you always forget about?"}]}],"tags":[]},{"id":"scene-43","no":"43","titleZh":"第 43 段","titleEn":"Part 43","sentences":[{"en":"You're at the grocery store shopping for essentials and you head home and then you realize, h I forgot again.","tc":"你在雜貨店購買必需品，然後回家，然後你意識到，我又忘了。","englishTokens":[{"type":"text","text":"You're at the "},{"type":"phrase","text":"grocery store","targetId":"phrase-grocery-store","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-43-001-001"},{"type":"text","text":" shopping for essentials and you head home and then you realize, h I forgot again."}]},{"en":"And what's your favorite thing to buy at the grocery store?","tc":"你最喜歡在雜貨店買什麼东西？","englishTokens":[{"type":"text","text":"And what's your favorite thing to buy at the "},{"type":"phrase","text":"grocery store","targetId":"phrase-grocery-store","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-43-002-001"},{"type":"text","text":"?"}]},{"en":"Now, let me show you a little bit of what I did today.","tc":"現在，讓我向您展示一下我今天所做的一些事情。","englishTokens":[{"type":"text","text":"Now, let me show you a little bit of what I did today."}]},{"en":"Some things I already bought for my apartment.","tc":"我已經為我的公寓購買了一些东西。","englishTokens":[{"type":"text","text":"Some things I already bought for my apartment."}]}],"tags":[]},{"id":"scene-44","no":"44","titleZh":"第 44 段","titleEn":"Part 44","sentences":[{"en":"Please excuse the mess.","tc":"請原諒混乱。","englishTokens":[{"type":"text","text":"Please excuse the mess."}]},{"en":"I already bought a mattress for my room.","tc":"我已經為我的房間買了床墊。","englishTokens":[{"type":"text","text":"I already bought a mattress for my room."}]},{"en":"I also bought some toothpaste, some hand soap, a new toothbrush, and a 30 pack of toilet paper.","tc":"我还買了一些牙膏，一些洗手液，一把新牙刷，还有30包衛生纸。","englishTokens":[{"type":"text","text":"I also bought some toothpaste, some hand soap, a new toothbrush, and a 30 pack of toilet paper."}]},{"en":"I forgot while I was editing my video to mention.","tc":"我在编辑視頻时忘了提及。","englishTokens":[{"type":"text","text":"I forgot while I was editing my video to mention."}]}],"tags":[]},{"id":"scene-45","no":"45","titleZh":"第 45 段","titleEn":"Part 45","sentences":[{"en":"I also got one more kitchen essential, a blender.","tc":"我还買了一件廚房必需品，搅拌機。","englishTokens":[{"type":"text","text":"I also got one more kitchen "},{"type":"word","text":"essential","targetId":"word-essential","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-45-001-001"},{"type":"text","text":", a blender."}]},{"en":"Very important for me.","tc":"對我來說非常重要。","englishTokens":[{"type":"text","text":"Very important for me."}]},{"en":"I need my smoothies every morning.","tc":"我每天早上都需要冰沙。","englishTokens":[{"type":"text","text":"I need my smoothies every morning."}]},{"en":"Kefir, milk.","tc":"開菲尔，牛奶。","englishTokens":[{"type":"text","text":"Kefir, milk."}]}],"tags":[]},{"id":"scene-46","no":"46","titleZh":"第 46 段","titleEn":"Part 46","sentences":[{"en":"Bye.","tc":"再见。","englishTokens":[{"type":"text","text":"Bye."}]},{"en":"Bananas, milk, kefir, and honey.","tc":"香蕉、牛奶、開菲尔和蜂蜜。","englishTokens":[{"type":"text","text":"Bananas, milk, kefir, and honey."}]},{"en":"Also, I forgot to mention I bought detergent to wash my clothes.","tc":"另外，我忘了說我買了洗衣粉來洗衣服。","englishTokens":[{"type":"text","text":"Also, I forgot to mention I bought detergent to wash my clothes."}]},{"en":"Now, I think those are all the essentials I bought today, but stick around for more videos to come about essentials in your house.","tc":"現在，我想這些就是我今天買的所有必需品，但請繼續觀看更多有關您家里必需品的視頻。","englishTokens":[{"type":"text","text":"Now, I think those are all the essentials I bought today, but stick around for more videos to come about essentials in your house."}]}],"tags":[]},{"id":"scene-47","no":"47","titleZh":"第 47 段","titleEn":"Part 47","sentences":[{"en":"This is my first time living alone, so I'm going to be buying lots of essentials that I never had to buy before.","tc":"這是我第一次独自生活，所以我将購買很多以前从未購買過的必需品。","englishTokens":[{"type":"text","text":"This is my first time living alone, so I'm going to be buying lots of essentials that I never had to buy before."}]},{"en":"Hello.","tc":"你好。","englishTokens":[{"type":"text","text":"Hello."}]},{"en":"Let's learn some house essentials.","tc":"讓我們學習一些家居必需品。","englishTokens":[{"type":"text","text":"Let's learn some house essentials."}]},{"en":"I am in my new apartment and I need to furnish it.","tc":"我在我的新公寓里，我需要装修它。","englishTokens":[{"type":"text","text":"I am in my new apartment and I need to furnish it."}]}],"tags":[]},{"id":"scene-48","no":"48","titleZh":"第 48 段","titleEn":"Part 48","sentences":[{"en":"So, join me in this slow English podcast.","tc":"那麼，加入我這個缓慢的英語播客吧。","englishTokens":[{"type":"text","text":"So, join me in this "},{"type":"phrase","text":"slow English podcast","targetId":"phrase-slow-english-podcast","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-189-01"},{"type":"text","text":"."}]},{"en":"I hope you learn some new vocabulary today.","tc":"我希望你今天學到一些新詞彙。","englishTokens":[{"type":"text","text":"I hope you learn some new vocabulary today."}]},{"en":"In my last video, I showed you guys what I had bought so far, but now I've bought even more.","tc":"在我的上一個視頻中，我向你們展示了到目前為止我買的东西，但現在我買了更多。","englishTokens":[{"type":"text","text":"In my last video, I showed you guys what I had bought "},{"type":"phrase","text":"so far","targetId":"phrase-so-far","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-191-01"},{"type":"text","text":", but now I've bought even more."}]},{"en":"So, let's learn some house essentials in English.","tc":"那麼，讓我們用英語學習一些居家必備知識吧。","englishTokens":[{"type":"text","text":"So, let's learn some house essentials in English."}]}],"tags":[]},{"id":"scene-49","no":"49","titleZh":"第 49 段","titleEn":"Part 49","sentences":[{"en":"I bought a couch.","tc":"我買了一張沙發。","englishTokens":[{"type":"text","text":"I bought a couch."}]},{"en":"I love this couch.","tc":"我喜歡這張沙發。","englishTokens":[{"type":"text","text":"I love this couch."}]},{"en":"It's so comfy.","tc":"真舒服。","englishTokens":[{"type":"text","text":"It's so comfy."}]},{"en":"A comfy couch is very important for a home.","tc":"一張舒适的沙發對于一個家來說非常重要。","englishTokens":[{"type":"text","text":"A comfy couch is very important for a home."}]}],"tags":[]},{"id":"scene-50","no":"50","titleZh":"第 50 段","titleEn":"Part 50","sentences":[{"en":"I love the color and I think it really ties the room together.","tc":"我喜歡這種颜色，我認為它確實将房間联系在一起。","englishTokens":[{"type":"text","text":"I love the color and I think it really ties the room together."}]},{"en":"When something ties the room together, it means it really synchronizes with everything in the room and makes it special.","tc":"當某物将房間联系在一起时，意味着它確實與房間中的一切同步并使其變得特別。","englishTokens":[{"type":"text","text":"When something ties the room together, it means it really synchronizes with everything in the room and makes it special."}]},{"en":"What do you think of my new couch?","tc":"你覺得我的新沙發怎麼樣？","englishTokens":[{"type":"text","text":"What do you think of my new couch?"}]},{"en":"Is it your style or maybe not so much?","tc":"這是你的风格还是不太喜歡？","englishTokens":[{"type":"text","text":"Is it your style or maybe not so much?"}]}],"tags":[]},{"id":"scene-51","no":"51","titleZh":"第 51 段","titleEn":"Part 51","sentences":[{"en":"I got a plant.","tc":"我有一株植物。","englishTokens":[{"type":"text","text":"I got a plant."}]},{"en":"Of course, plants are the most important part of a home, and I want to fill this place up with plants completely.","tc":"當然，植物是一個家最重要的部分，我想讓這個地方完全被植物填滿。","englishTokens":[{"type":"text","text":"Of course, plants are the most important part of a home, and I want to fill this place up with plants completely."}]},{"en":"Plants bring abundance, prosperity, and money.","tc":"植物帶來丰富、繁榮和金錢。","englishTokens":[{"type":"text","text":"Plants bring abundance, prosperity, and money."}]},{"en":"It's a good idea to have plants in your home if you don't already.","tc":"如果您还沒有在家中種植植物，那麼這是一個好主意。","englishTokens":[{"type":"text","text":"It's a good idea to "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-51-004-001"},{"type":"text","text":" plants in your home if you don't already."}]}],"tags":[]},{"id":"scene-52","no":"52","titleZh":"第 52 段","titleEn":"Part 52","sentences":[{"en":"I got a mirror, of course.","tc":"當然，我有一面镜子。","englishTokens":[{"type":"text","text":"I got a mirror, of course."}]},{"en":"I love how mirrors look in a space like this.","tc":"我喜歡镜子在這樣的空間中的樣子。","englishTokens":[{"type":"text","text":"I love how mirrors look in a space like this."}]},{"en":"I just have to be very careful.","tc":"我只需要非常小心。","englishTokens":[{"type":"text","text":"I just "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-52-003-001"},{"type":"text","text":" to be very careful."}]},{"en":"My dad says that that mirror can cause a fire supposedly.","tc":"我爸爸說那面镜子據說會引起火灾。","englishTokens":[{"type":"text","text":"My dad says that that mirror can cause a fire supposedly."}]}],"tags":[]},{"id":"scene-53","no":"53","titleZh":"第 53 段","titleEn":"Part 53","sentences":[{"en":"I don't know.","tc":"我不知道。","englishTokens":[{"type":"text","text":"I don't know."}]},{"en":"But I love how that mirror looks right there.","tc":"但我喜歡那面镜子的樣子。","englishTokens":[{"type":"text","text":"But I love how that mirror looks right there."}]},{"en":"I don't want to move it away from the sun because it looks so good right there.","tc":"我不想把它移離太陽，因為它就在那里看起來很好。","englishTokens":[{"type":"text","text":"I don't want to move it away from the sun because it looks so good right there."}]},{"en":"But my dad says the sun reflecting off of the mirror can cause a fire.","tc":"但我爸爸說镜子反射的陽光會引起火灾。","englishTokens":[{"type":"text","text":"But my dad says the sun reflecting off of the mirror can cause a fire."}]}],"tags":[]},{"id":"scene-54","no":"54","titleZh":"第 54 段","titleEn":"Part 54","sentences":[{"en":"I don't know.","tc":"我不知道。","englishTokens":[{"type":"text","text":"I don't know."}]},{"en":"I love how it looks right there.","tc":"我喜歡它在那里的樣子。","englishTokens":[{"type":"text","text":"I love how it looks right there."}]},{"en":"I don't want to move it someplace else.","tc":"我不想把它移到其他地方。","englishTokens":[{"type":"text","text":"I don't want to move it someplace else."}]},{"en":"I also have my yoga mat.","tc":"我也有我的瑜伽墊。","englishTokens":[{"type":"text","text":"I also "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-54-004-001"},{"type":"text","text":" my yoga mat."}]}],"tags":[]},{"id":"scene-55","no":"55","titleZh":"第 55 段","titleEn":"Part 55","sentences":[{"en":"Of course, I hide it behind the mirror just to keep things looking tidy.","tc":"當然，我把它藏在镜子後面只是為了保持东西看起來整潔。","englishTokens":[{"type":"text","text":"Of course, I hide it behind the mirror just to keep things looking tidy."}]},{"en":"Tidy and clean.","tc":"整潔、乾淨。","englishTokens":[{"type":"text","text":"Tidy and clean."}]},{"en":"With everything in its place.","tc":"一切都各就其位。","englishTokens":[{"type":"text","text":"With everything in its place."}]},{"en":"I also got another plant.","tc":"我还得到了另一株植物。","englishTokens":[{"type":"text","text":"I also got another plant."}]}],"tags":[]},{"id":"scene-56","no":"56","titleZh":"第 56 段","titleEn":"Part 56","sentences":[{"en":"Actually, this plant is a Brazil tree.","tc":"實際上，這種植物是巴西樹。","englishTokens":[{"type":"text","text":"Actually, this plant is a Brazil tree."}]},{"en":"A Brazilian tree.","tc":"巴西樹。","englishTokens":[{"type":"text","text":"A Brazilian tree."}]},{"en":"I think I'll explain the sticky notes in a minute.","tc":"我想我會在一分鐘內解釋便籤。","englishTokens":[{"type":"text","text":"I think I'll explain the sticky notes in a minute."}]},{"en":"Don't worry.","tc":"別担心。","englishTokens":[{"type":"text","text":"Don't worry."}]}],"tags":[]},{"id":"scene-57","no":"57","titleZh":"第 57 段","titleEn":"Part 57","sentences":[{"en":"I love Brazil trees.","tc":"我喜歡巴西樹。","englishTokens":[{"type":"text","text":"I love Brazil trees."}]},{"en":"I've always had a Brazil tree in my room and they're so pretty.","tc":"我的房間里一直有一棵巴西樹，它們非常漂亮。","englishTokens":[{"type":"text","text":"I've always had a Brazil tree in my room and they're so pretty."}]},{"en":"The air feels so much cleaner and they don't need any sun and they barely need water.","tc":"空氣感覺乾淨多了，他們不需要任何陽光，也几乎不需要水。","englishTokens":[{"type":"text","text":"The air feels so much cleaner and they don't need any sun and they barely need water."}]},{"en":"Only once a week.","tc":"每周一次。","englishTokens":[{"type":"text","text":"Only once a week."}]}],"tags":[]},{"id":"scene-58","no":"58","titleZh":"第 58 段","titleEn":"Part 58","sentences":[{"en":"I even keep a compost to water my two plants with the nutrients from my compost.","tc":"我什至保留堆肥，用堆肥中的养分浇灌我的两棵植物。","englishTokens":[{"type":"text","text":"I even keep a compost to water my two plants with the nutrients from my compost."}]},{"en":"Do you have any plants?","tc":"你有植物嗎？","englishTokens":[{"type":"text","text":"Do you "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-58-002-001"},{"type":"text","text":" any plants?"}]},{"en":"Do you keep a compost for your plants?","tc":"你為你的植物保留堆肥嗎？","englishTokens":[{"type":"text","text":"Do you keep a compost for your plants?"}]},{"en":"I got some throw blankets.","tc":"我有一些毯子。","englishTokens":[{"type":"text","text":"I got some throw blankets."}]}],"tags":[]},{"id":"scene-59","no":"59","titleZh":"第 59 段","titleEn":"Part 59","sentences":[{"en":"Throw blankets are smaller than the average blanket.","tc":"毯子比普通毯子小。","englishTokens":[{"type":"text","text":"Throw blankets are smaller than the average blanket."}]},{"en":"This is what a normal blanket looks like.","tc":"這就是普通毯子的樣子。","englishTokens":[{"type":"text","text":"This is what a normal blanket looks like."}]},{"en":"And this is what a throw blanket looks like.","tc":"這就是毯子的樣子。","englishTokens":[{"type":"text","text":"And this is what a throw blanket looks like."}]},{"en":"See, they're much smaller.","tc":"看，它們小得多。","englishTokens":[{"type":"text","text":"See, they're much smaller."}]}],"tags":[]},{"id":"scene-60","no":"60","titleZh":"第 60 段","titleEn":"Part 60","sentences":[{"en":"You just use them to throw on when you're watching a movie or just working, I guess.","tc":"我猜你只是在看電影或工作时用它們來穿。","englishTokens":[{"type":"text","text":"You just use them to throw on when you're watching a movie or just working, I guess."}]},{"en":"I got these side tables to keep some junk in like my jump rope or my exercise bands.","tc":"我買了這些邊桌來存放一些垃圾，比如我的跳繩或健身帶。","englishTokens":[{"type":"text","text":"I got these side tables to keep some junk in like my jump rope or my exercise bands."}]},{"en":"I just like these so I can set my cup on them while I'm watching a movie.","tc":"我只是喜歡這些，這樣我就可以在看電影时把杯子放在上面。","englishTokens":[{"type":"text","text":"I just like these so I can set my cup on them while I'm watching a movie."}]},{"en":"Now, one of my favorite parts, the projector.","tc":"現在，我最喜歡的部件之一是投影仪。","englishTokens":[{"type":"text","text":"Now, one of my favorite parts, the projector."}]}],"tags":[]},{"id":"scene-61","no":"61","titleZh":"第 61 段","titleEn":"Part 61","sentences":[{"en":"This projector looks so nice at night.","tc":"這台投影機在晚上看起來非常漂亮。","englishTokens":[{"type":"text","text":"This projector looks so nice at night."}]},{"en":"It's such a big screen.","tc":"屏幕這麼大。","englishTokens":[{"type":"text","text":"It's such a big screen."}]},{"en":"If you're deciding between buying a TV or considering buying a projector, I have your answer.","tc":"如果您正在決定購買電視还是考慮購買投影仪，我有您的答案。","englishTokens":[{"type":"text","text":"If you're deciding between buying a TV or considering buying a projector, I "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-61-003-001"},{"type":"text","text":" your answer."}]},{"en":"Get the projector.","tc":"获取投影仪。","englishTokens":[{"type":"usage","text":"Get","targetId":"usage-get-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-61-004-001"},{"type":"text","text":" the projector."}]}],"tags":[]},{"id":"scene-62","no":"62","titleZh":"第 62 段","titleEn":"Part 62","sentences":[{"en":"I love mine.","tc":"我愛我的。","englishTokens":[{"type":"text","text":"I love mine."}]},{"en":"I have been watching Game of Thrones on this every night.","tc":"我每天晚上都在看《权力的游戏》。","englishTokens":[{"type":"text","text":"I "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-62-002-001"},{"type":"text","text":" been watching Game of Thrones on this every night."}]},{"en":"I just started watching this series.","tc":"我剛剛開始看這個系列。","englishTokens":[{"type":"text","text":"I just started watching this series."}]},{"en":"It's so good.","tc":"真是太好了。","englishTokens":[{"type":"text","text":"It's so good."}]}],"tags":[]},{"id":"scene-63","no":"63","titleZh":"第 63 段","titleEn":"Part 63","sentences":[{"en":"I'm obsessed.","tc":"我很着迷。","englishTokens":[{"type":"text","text":"I'm obsessed."}]},{"en":"I have been watching Game of Thrones.","tc":"我一直在看《权力的游戏》。","englishTokens":[{"type":"text","text":"I "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-63-002-001"},{"type":"text","text":" been watching Game of Thrones."}]},{"en":"What have you been watching?","tc":"你在看什麼？","englishTokens":[{"type":"text","text":"What "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-63-003-001"},{"type":"text","text":" you been watching?"}]},{"en":"Remember, we use have been when something started in the past but continues in the present.","tc":"請记住，當某件事从過去開始但現在仍在繼續时，我們使用“bevewas”。","englishTokens":[{"type":"text","text":"Remember, we use "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-63-004-001"},{"type":"text","text":" been when something started in the past but continues in the present."}]}],"tags":[]},{"id":"scene-64","no":"64","titleZh":"第 64 段","titleEn":"Part 64","sentences":[{"en":"I have this little whiteboard that I write down little things that I have to do.","tc":"我有一块小白板，用來寫下我必須做的小事情。","englishTokens":[{"type":"text","text":"I "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-64-001-001"},{"type":"text","text":" this little whiteboard that I write down little things that I "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-64-001-002"},{"type":"text","text":" to do."}]},{"en":"It's my to-do list.","tc":"這是我的待办事项清單。","englishTokens":[{"type":"text","text":"It's my to-do list."}]},{"en":"Ignore all of this mess of boxes and Ethernet cables and my pile of books left in the corner.","tc":"忽略所有這些乱七八糟的盒子和以太網電缆以及我留在角落里的一堆書。","englishTokens":[{"type":"text","text":"Ignore all of this mess of boxes and Ethernet cables and my pile of books left in the corner."}]},{"en":"There's still a lot of work to be done.","tc":"还有很多工作要做。","englishTokens":[{"type":"text","text":"There's still a lot of work to be done."}]}],"tags":[]},{"id":"scene-65","no":"65","titleZh":"第 65 段","titleEn":"Part 65","sentences":[{"en":"But now moving on to the kitchen.","tc":"但現在转向廚房。","englishTokens":[{"type":"text","text":"But now moving on to the kitchen."}]},{"en":"I bought two swivel chairs.","tc":"我買了两張转椅。","englishTokens":[{"type":"text","text":"I bought two swivel chairs."}]},{"en":"Swivel chairs because they swivel from side to side.","tc":"转椅，因為它們可以左右旋转。","englishTokens":[{"type":"text","text":"Swivel chairs because they swivel from side to side."}]},{"en":"They are perfect for us to eat at our little kitchen bar.","tc":"它們非常适合我們在我們的小廚房吧台吃飯。","englishTokens":[{"type":"text","text":"They are perfect for us to eat at our little kitchen bar."}]}],"tags":[]},{"id":"scene-66","no":"66","titleZh":"第 66 段","titleEn":"Part 66","sentences":[{"en":"Also, excuse the broom.","tc":"另外，請原諒扫帚。","englishTokens":[{"type":"text","text":"Also, excuse the broom."}]},{"en":"I was sweeping and I just left the entire mess in the corner.","tc":"我正在扫地，我把所有乱七八糟的东西留在了角落里。","englishTokens":[{"type":"text","text":"I was sweeping and I just left the entire mess in the corner."}]},{"en":"But speaking of brooms, I bought a mop.","tc":"但是說到扫帚，我買了一把拖把。","englishTokens":[{"type":"text","text":"But speaking of brooms, I bought a mop."}]},{"en":"I can finally mop.","tc":"我終于可以拖地了。","englishTokens":[{"type":"text","text":"I can finally mop."}]}],"tags":[]},{"id":"scene-67","no":"67","titleZh":"第 67 段","titleEn":"Part 67","sentences":[{"en":"And of course, I also had to get a bucket.","tc":"當然，我还得拿一個水桶。","englishTokens":[{"type":"text","text":"And of course, I also had to "},{"type":"usage","text":"get","targetId":"usage-get-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-67-001-001"},{"type":"text","text":" a bucket."}]},{"en":"Now the most important part, the refrigerator.","tc":"現在最重要的部分，冰箱。","englishTokens":[{"type":"text","text":"Now the most important part, the refrigerator."}]},{"en":"Finally, I was eating tuna every day.","tc":"終于，我每天都吃金枪魚了。","englishTokens":[{"type":"text","text":"Finally, I was eating tuna every day."}]},{"en":"But finally, we got the refrigerator.","tc":"但最後，我們得到了冰箱。","englishTokens":[{"type":"text","text":"But finally, we got the refrigerator."}]}],"tags":[]},{"id":"scene-68","no":"68","titleZh":"第 68 段","titleEn":"Part 68","sentences":[{"en":"It was so stressful actually because we ordered the refrigerator, it arrived and it was installed.","tc":"實際上壓力很大，因為我們訂購了冰箱，冰箱到貨并安装完畢。","englishTokens":[{"type":"text","text":"It was so stressful actually because we ordered the refrigerator, it arrived and it was installed."}]},{"en":"We waited 24 hours and then we turned on the appliance.","tc":"我們等了24小时，然後打開了設備。","englishTokens":[{"type":"text","text":"We waited 24 hours and then we turned on the appliance."}]},{"en":"We plugged in the refrigerator and it didn't work.","tc":"我們给冰箱插上電源，但它不起作用。","englishTokens":[{"type":"text","text":"We plugged in the refrigerator and it didn't work."}]},{"en":"It wouldn't get cold.","tc":"不會冷。","englishTokens":[{"type":"text","text":"It wouldn't "},{"type":"usage","text":"get","targetId":"usage-get-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-68-004-001"},{"type":"text","text":" cold."}]}],"tags":[]},{"id":"scene-69","no":"69","titleZh":"第 69 段","titleEn":"Part 69","sentences":[{"en":"So, all of our food went bad.","tc":"所以，我們所有的食物都變質了。","englishTokens":[{"type":"text","text":"So, all of our food went bad."}]},{"en":"The fruit and vegetables and milk and yogurt all went bad.","tc":"水果、蔬菜、牛奶、酸奶都變質了。","englishTokens":[{"type":"text","text":"The fruit and vegetables and milk and yogurt all went bad."}]},{"en":"So, we had to call the repair man and he came and fixed our refrigerator.","tc":"所以，我們不得不打電话给修理工，他來修好了我們的冰箱。","englishTokens":[{"type":"text","text":"So, we had to call the repair man and he came and fixed our refrigerator."}]},{"en":"We had to pay more, of course, but nevertheless, we have a fridge.","tc":"當然，我們必須支付更多費用，但尽管如此，我們还是有一台冰箱。","englishTokens":[{"type":"text","text":"We had to pay more, of course, but nevertheless, we "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-69-004-001"},{"type":"text","text":" a fridge."}]}],"tags":[]},{"id":"scene-70","no":"70","titleZh":"第 70 段","titleEn":"Part 70","sentences":[{"en":"Something else that's very important, the toppers.","tc":"还有一些非常重要的事情，即礼帽。","englishTokens":[{"type":"phrase","text":"Something else","targetId":"phrase-something-else","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-277-01"},{"type":"text","text":" that's very important, the toppers."}]},{"en":"The topper wear big toppers, small toppers, and medium-sized tuppers.","tc":"礼帽分為大礼帽、小礼帽、中礼帽。","englishTokens":[{"type":"text","text":"The topper wear big toppers, small toppers, and medium-sized tuppers."}]},{"en":"Some more spices, sauces, and cooking oil.","tc":"一些更多的香料、醬汁和食用油。","englishTokens":[{"type":"text","text":"Some more spices, sauces, and cooking oil."}]},{"en":"A knife holder.","tc":"刀架。","englishTokens":[{"type":"text","text":"A knife holder."}]}],"tags":[]},{"id":"scene-71","no":"71","titleZh":"第 71 段","titleEn":"Part 71","sentences":[{"en":"More plates.","tc":"更多板块。","englishTokens":[{"type":"text","text":"More plates."}]},{"en":"More mugs.","tc":"更多杯子。","englishTokens":[{"type":"text","text":"More mugs."}]},{"en":"More spoons.","tc":"更多勺子。","englishTokens":[{"type":"text","text":"More spoons."}]},{"en":"More forks.","tc":"更多叉子。","englishTokens":[{"type":"text","text":"More forks."}]}],"tags":[]},{"id":"scene-72","no":"72","titleZh":"第 72 段","titleEn":"Part 72","sentences":[{"en":"Some butter knives for spreading butter.","tc":"一些用于涂抹黄油的黄油刀。","englishTokens":[{"type":"text","text":"Some butter knives for spreading butter."}]},{"en":"A whisk, a cutting board dirty from my berries, a cheese grater, and a lime squeezer.","tc":"一個搅拌器、一块被我的浆果弄脏的切菜板、一個奶酪刨丝器和一個酸橙榨汁機。","englishTokens":[{"type":"text","text":"A whisk, a cutting board dirty from my berries, a cheese grater, and a lime squeezer."}]},{"en":"Some little things like paper towels, trash bags, a coffee machine.","tc":"一些小东西，如纸巾、垃圾袋、咖啡機。","englishTokens":[{"type":"text","text":"Some little things like paper towels, trash bags, a coffee machine."}]},{"en":"Even though I don't drink coffee, my roommate does.","tc":"尽管我不喝咖啡，但我的室友却喝咖啡。","englishTokens":[{"type":"text","text":"Even though I don't drink coffee, my roommate does."}]}],"tags":[]},{"id":"scene-73","no":"73","titleZh":"第 73 段","titleEn":"Part 73","sentences":[{"en":"I also got a brand new rug.","tc":"我还得到了一張全新的地毯。","englishTokens":[{"type":"text","text":"I also got a brand new rug."}]},{"en":"I think it ties in with the room perfectly.","tc":"我認為它與房間完美地结合在一起。","englishTokens":[{"type":"text","text":"I think it ties in with the room perfectly."}]},{"en":"That's my new ring light.","tc":"這是我的新環形燈。","englishTokens":[{"type":"text","text":"That's my new ring light."}]},{"en":"I got a toothbrush holder and a bath towel.","tc":"我有一個牙刷架和一条浴巾。","englishTokens":[{"type":"text","text":"I got a toothbrush holder and a bath towel."}]}],"tags":[]},{"id":"scene-74","no":"74","titleZh":"第 74 段","titleEn":"Part 74","sentences":[{"en":"And I got some new things for my videos.","tc":"我的視頻有了一些新东西。","englishTokens":[{"type":"text","text":"And I got some new things for my videos."}]},{"en":"My mom bought me these bee lights for Miss Honey, a new tripod with a ring light and a pillow to be more comfortable recording.","tc":"我媽媽為MissHoney買了這些蜜蜂燈，一個帶有環形燈和枕頭的新三脚架，以便更舒适地錄制。","englishTokens":[{"type":"text","text":"My mom bought me these bee lights for Miss Honey, a new tripod with a ring light and a pillow to be more comfortable recording."}]},{"en":"I also had to get these earplugs because it's so noisy outside.","tc":"我还必須戴上這些耳塞，因為外面太吵了。","englishTokens":[{"type":"text","text":"I also had to "},{"type":"usage","text":"get","targetId":"usage-get-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-74-003-001"},{"type":"text","text":" these earplugs because it's so noisy outside."}]},{"en":"I couldn't sleep without them.","tc":"沒有他們我就睡不着。","englishTokens":[{"type":"text","text":"I couldn't sleep without them."}]}],"tags":[]},{"id":"scene-75","no":"75","titleZh":"第 75 段","titleEn":"Part 75","sentences":[{"en":"This is my desk filled with lots of junk.","tc":"這是我的桌子，里面堆滿了垃圾。","englishTokens":[{"type":"text","text":"This is my desk filled with lots of junk."}]},{"en":"My lotion.","tc":"我的乳液。","englishTokens":[{"type":"text","text":"My lotion."}]},{"en":"This thing is amazing.","tc":"這件事太神奇了。","englishTokens":[{"type":"text","text":"This thing is amazing."}]},{"en":"Do you know what this is?","tc":"你知道這是什麼嗎？","englishTokens":[{"type":"text","text":"Do you know what this is?"}]}],"tags":[]},{"id":"scene-76","no":"76","titleZh":"第 76 段","titleEn":"Part 76","sentences":[{"en":"Some sticky notes.","tc":"一些便利贴。","englishTokens":[{"type":"text","text":"Some sticky notes."}]},{"en":"My portable charger.","tc":"我的便携式充電器。","englishTokens":[{"type":"text","text":"My portable "},{"type":"word","text":"charger","targetId":"word-charger","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-302-01"},{"type":"text","text":"."}]},{"en":"My nail clippers.","tc":"我的指甲刀。","englishTokens":[{"type":"text","text":"My nail clippers."}]},{"en":"A humidifier, a mug with some coffee, my glasses, my computer, and the mouse.","tc":"一個加濕器、一個装有咖啡的杯子、我的眼镜、我的電腦和鼠標。","englishTokens":[{"type":"text","text":"A humidifier, a mug with some coffee, my glasses, my computer, and the mouse."}]}],"tags":[]},{"id":"scene-77","no":"77","titleZh":"第 77 段","titleEn":"Part 77","sentences":[{"en":"And now, let me explain all of these sticky notes.","tc":"現在，讓我解釋一下所有這些便利贴。","englishTokens":[{"type":"text","text":"And now, let me explain all of these sticky notes."}]},{"en":"This one's a little bit smudged.","tc":"這個有点脏了。","englishTokens":[{"type":"text","text":"This one's a little bit smudged."}]},{"en":"I got a tip from a new friend of mine.","tc":"我从一位新朋友那里得到了一個建议。","englishTokens":[{"type":"text","text":"I got a tip from a new friend of mine."}]},{"en":"She's Chinese and when she learned English, she said that she used to put sticky notes with the names in English on every object in her house.","tc":"她是中國人，當她學習英語时，她說她曾經在家里的每件物品上贴上帶有英文名称的便籤。","englishTokens":[{"type":"text","text":"She's Chinese and when she learned English, she said that she used to put sticky notes with the names in English on every object in her house."}]}],"tags":[]},{"id":"scene-78","no":"78","titleZh":"第 78 段","titleEn":"Part 78","sentences":[{"en":"That way she learned the name of everything around her in English first, not unnecessary English words that you never use.","tc":"這樣，她首先學會了周围一切事物的英文名称，而不是那些你从不使用的不必要的英文單詞。","englishTokens":[{"type":"text","text":"That way she learned the name of everything around her in English first, not unnecessary English words that you never use."}]},{"en":"Therefore, you forget eventually with the sticky notes.","tc":"因此，你最終會忘记便利贴。","englishTokens":[{"type":"text","text":"Therefore, you forget eventually with the sticky notes."}]},{"en":"You see them all day.","tc":"你整天都能看到它們。","englishTokens":[{"type":"text","text":"You see them all day."}]},{"en":"Your brain is always thinking in English because of those sticky notes.","tc":"因為那些便利贴，你的大腦總是用英語思考。","englishTokens":[{"type":"text","text":"Your brain is always thinking in English because of those sticky notes."}]}],"tags":[]},{"id":"scene-79","no":"79","titleZh":"第 79 段","titleEn":"Part 79","sentences":[{"en":"So, I'm doing the same with Chinese.","tc":"所以，我對中文也做了同樣的事情。","englishTokens":[{"type":"text","text":"So, I'm doing the same with Chinese."}]},{"en":"I followed my friend's advice and I wrote down every word from around my house onto a sticky note and I stuck them onto each object.","tc":"我聽从了朋友的建议，把我家周围的每一個字都寫在一張便利贴上，然後把它們贴在每個物體上。","englishTokens":[{"type":"text","text":"I followed my friend's advice and I wrote down every word from around my house onto a sticky note and I stuck them onto each object."}]},{"en":"My computer, my table, my plants, and even on my kitchen chair.","tc":"我的電腦、我的桌子、我的植物，甚至我的廚房椅子上。","englishTokens":[{"type":"text","text":"My computer, my table, my plants, and even on my kitchen chair."}]},{"en":"That's been a super useful tip.","tc":"這是一個非常有用的提示。","englishTokens":[{"type":"text","text":"That's been a super useful tip."}]}],"tags":[]},{"id":"scene-80","no":"80","titleZh":"第 80 段","titleEn":"Part 80","sentences":[{"en":"I recommend you try it, too.","tc":"我建议你也嘗試一下。","englishTokens":[{"type":"text","text":"I recommend you try it, too."}]},{"en":"These were the essentials I bought for my home so far.","tc":"這些是迄今為止我為家里購買的必需品。","englishTokens":[{"type":"text","text":"These were the essentials I bought for my home "},{"type":"phrase","text":"so far","targetId":"phrase-so-far","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-80-002-001"},{"type":"text","text":"."}]},{"en":"I still have a few things to get, but my apartment isn't fully furnished yet.","tc":"我还有一些东西要拿，但我的公寓还沒有家具齐全。","englishTokens":[{"type":"text","text":"I still "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-80-003-001"},{"type":"text","text":" a few things to "},{"type":"usage","text":"get","targetId":"usage-get-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-80-003-002"},{"type":"text","text":", but my apartment isn't fully furnished yet."}]},{"en":"What is an essential in your home?","tc":"你家里的必需品是什麼？","englishTokens":[{"type":"text","text":"What is an "},{"type":"word","text":"essential","targetId":"word-essential","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-80-004-001"},{"type":"text","text":" in your home?"}]}],"tags":[]},{"id":"scene-81","no":"81","titleZh":"第 81 段","titleEn":"Part 81","sentences":[{"en":"What's the most important thing in your house?","tc":"你家里最重要的东西是什麼？","englishTokens":[{"type":"text","text":"What's the most important thing in your house?"}]},{"en":"Mine is the couch.","tc":"我的是沙發。","englishTokens":[{"type":"text","text":"Mine is the couch."}]},{"en":"It makes any space feel like a home.","tc":"它讓任何空間都感覺像家一樣。","englishTokens":[{"type":"text","text":"It makes any space feel like a home."}]},{"en":"And it lets me and my family, me and my friends sit down and laugh together.","tc":"它讓我和我的家人、我和我的朋友坐下來一起歡笑。","englishTokens":[{"type":"text","text":"And it lets me and my family, me and my friends sit down and laugh together."}]}],"tags":[]},{"id":"scene-82","no":"82","titleZh":"第 82 段","titleEn":"Part 82","sentences":[{"en":"We are going to take a flight.","tc":"我們要乘飛機了。","englishTokens":[{"type":"text","text":"We are going to "},{"type":"usage","text":"take","targetId":"usage-take-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-325-01"},{"type":"text","text":" a flight."}]},{"en":"Join us.","tc":"加入我們。","englishTokens":[{"type":"text","text":"Join us."}]},{"en":"The automatic doors slide open and right away you see the FIDS port, the flight information display system where you can see your flight status, whether it's on time, delayed, or cancelled.","tc":"自動門滑開後，您立即會看到FIDS端口，這是航班信息显示系统，您可以在其中查看航班状态，無论是准点、延誤还是取消。","englishTokens":[{"type":"text","text":"The automatic doors slide open and right away you see the FIDS port, the flight information display system where you can see your flight status, whether it's on time, "},{"type":"word","text":"delayed","targetId":"word-delayed","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-327-01"},{"type":"text","text":", or cancelled."}]},{"en":"Then we found our check-in counter.","tc":"然後我們找到了登機櫃台。","englishTokens":[{"type":"text","text":"Then we found our check-in counter."}]}],"tags":[]},{"id":"scene-83","no":"83","titleZh":"第 83 段","titleEn":"Part 83","sentences":[{"en":"We were flying with Air Asia, so we had to find the Air Asia check-in counter.","tc":"我們乘坐的是亚洲航空的航班，所以我們必須找到亚洲航空的值機櫃台。","englishTokens":[{"type":"text","text":"We were flying with Air Asia, so we had to find the Air Asia check-in counter."}]},{"en":"I am in line to check in.","tc":"我正在排队办理登機手續。","englishTokens":[{"type":"text","text":"I am in line to "},{"type":"phrase","text":"check in","targetId":"phrase-check-in","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-330-01"},{"type":"text","text":"."}]},{"en":"Some people prefer the self check-in kiosk, but I don't like this self check-in system as much.","tc":"有些人更喜歡自助值機亭，但我不太喜歡這種自助值機系统。","englishTokens":[{"type":"text","text":"Some people prefer the self check-in kiosk, but I don't like this self check-in system as much."}]},{"en":"Sometimes it makes me nervous.","tc":"有时這讓我感到緊張。","englishTokens":[{"type":"text","text":"Sometimes it makes me nervous."}]}],"tags":[]},{"id":"scene-84","no":"84","titleZh":"第 84 段","titleEn":"Part 84","sentences":[{"en":"I prefer to check in at a counter with a real person.","tc":"我更喜歡在櫃台與真人一起办理登機手續。","englishTokens":[{"type":"text","text":"I prefer to "},{"type":"phrase","text":"check in","targetId":"phrase-check-in","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-84-001-001"},{"type":"text","text":" at a counter with a real person."}]},{"en":"What about you?","tc":"你呢？","englishTokens":[{"type":"text","text":"What about you?"}]},{"en":"Do you prefer the check-in counter or the self check-in kiosk?","tc":"您更喜歡櫃台值機还是自助值機終端？","englishTokens":[{"type":"text","text":"Do you prefer the check-in counter or the self check-in kiosk?"}]},{"en":"I am taking the escalator, the electric stairs.","tc":"我乘坐自動扶梯，電動樓梯。","englishTokens":[{"type":"text","text":"I am taking the escalator, the electric stairs."}]}],"tags":[]},{"id":"scene-85","no":"85","titleZh":"第 85 段","titleEn":"Part 85","sentences":[{"en":"You can also take the elevator, but only if you need it.","tc":"您也可以乘坐電梯，但前提是您需要。","englishTokens":[{"type":"text","text":"You can also "},{"type":"usage","text":"take","targetId":"usage-take-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-85-001-001"},{"type":"text","text":" the elevator, but only if you need it."}]},{"en":"Maybe if you have big luggage or you're in a wheelchair, but it's exclusive for people who need the elevator.","tc":"也许如果你有大件行李或者你坐在轮椅上，但它是專門為需要電梯的人准備的。","englishTokens":[{"type":"text","text":"Maybe if you have big "},{"type":"word","text":"luggage","targetId":"word-luggage","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-338-01"},{"type":"text","text":" or you're in a wheelchair, but it's exclusive for people who need the elevator."}]},{"en":"I'm Okay with taking the escalator, the electric stairs.","tc":"我可以乘坐自動扶梯、電動樓梯。","englishTokens":[{"type":"text","text":"I'm Okay with taking the escalator, the electric stairs."}]},{"en":"We got some lunch before our flight.","tc":"我們在起飛前吃了一些午餐。","englishTokens":[{"type":"text","text":"We got some lunch before our flight."}]}],"tags":[]},{"id":"scene-86","no":"86","titleZh":"第 86 段","titleEn":"Part 86","sentences":[{"en":"We were close to international arrivals, but we had to get to international departures because we were departing, not arriving.","tc":"我們接近國際航班到達，但我們必須到達國際出發，因為我們是出發，而不是到達。","englishTokens":[{"type":"text","text":"We were close to international arrivals, but we had to "},{"type":"usage","text":"get","targetId":"usage-get-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-86-001-001"},{"type":"text","text":" to international departures because we were departing, not arriving."}]},{"en":"I got my passport ready and my ticket and we passed through the security checkpoint where you have to take out anything metal like keys, bracelets, coins or change.","tc":"我准備好了護照和機票，然後我們通過了安全檢查站，在那里你必須取出任何金屬物品，如钥匙、手镯、硬币或零錢。","englishTokens":[{"type":"text","text":"I got my "},{"type":"word","text":"passport","targetId":"word-passport","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-342-01"},{"type":"text","text":" ready and my ticket and we passed through the "},{"type":"word","text":"security","targetId":"word-security","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-342-02"},{"type":"text","text":" "},{"type":"word","text":"checkpoint","targetId":"word-checkpoint","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-342-03"},{"type":"text","text":" where you have to take out anything metal like keys, bracelets, coins or change."}]},{"en":"Your computer or laptop, your phone, your headphones, and sometimes even your shoes.","tc":"您的計算機或笔记本電腦、手機、耳機，有时甚至是鞋子。","englishTokens":[{"type":"text","text":"Your computer or "},{"type":"word","text":"laptop","targetId":"word-laptop","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-343-01"},{"type":"text","text":", your phone, your headphones, and sometimes even your shoes."}]},{"en":"The queue, or line, was very long, but once we got through security, we entered the airport area.","tc":"队列很長，但是一旦通過安檢，我們就进入了機場區域。","englishTokens":[{"type":"text","text":"The queue, or line, was very long, but once we got through "},{"type":"word","text":"security","targetId":"word-security","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-86-004-001"},{"type":"text","text":", we entered the "},{"type":"word","text":"airport","targetId":"word-airport","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-86-004-002"},{"type":"text","text":" area."}]}],"tags":[]},{"id":"scene-87","no":"87","titleZh":"第 87 段","titleEn":"Part 87","sentences":[{"en":"I always love the duty free stores.","tc":"我一直很喜歡免税店。","englishTokens":[{"type":"text","text":"I always love the duty free stores."}]},{"en":"They're super expensive, but I like looking through each store while I wait.","tc":"它們非常昂貴，但我喜歡在等待时浏覽每家商店。","englishTokens":[{"type":"text","text":"They're super expensive, but I like looking through each store while I wait."}]},{"en":"We walk past Cartiier and Starbucks as we make our way to our gate by following the signs with gate number instructions on them.","tc":"當我們按照標有登機口號碼說明的標志前往登機口时，我們會經過卡地亚和星巴克。","englishTokens":[{"type":"text","text":"We walk past Cartiier and Starbucks as we "},{"type":"usage","text":"make","targetId":"usage-make-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-87-003-001"},{"type":"text","text":" our way to our gate by following the signs with gate number instructions on them."}]},{"en":"It was super useful that they showed how long the walk to each gate was.","tc":"他們显示了到達每個登機口的步行时間，這非常有用。","englishTokens":[{"type":"text","text":"It was super useful that they showed how long the walk to each gate was."}]}],"tags":[]},{"id":"scene-88","no":"88","titleZh":"第 88 段","titleEn":"Part 88","sentences":[{"en":"10 minutes, 5 minutes, 1 minute.","tc":"10分鐘，5分鐘，1分鐘。","englishTokens":[{"type":"text","text":"10 minutes, 5 minutes, 1 minute."}]},{"en":"That way, you're not super rushed or in a hurry to get to your gate.","tc":"這樣，您就不會超级匆忙或急于到達登機口。","englishTokens":[{"type":"text","text":"That way, you're not super rushed or in a hurry to "},{"type":"usage","text":"get","targetId":"usage-get-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-88-002-001"},{"type":"text","text":" to your gate."}]},{"en":"When you still have lots of time to get there.","tc":"當你还有很多时間到達那里时。","englishTokens":[{"type":"text","text":"When you still "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-88-003-001"},{"type":"text","text":" lots of time to "},{"type":"usage","text":"get","targetId":"usage-get-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-88-003-002"},{"type":"text","text":" there."}]},{"en":"When it's only a five minute walk and you also know if you need to hurry if you need to rush to your gate.","tc":"當步行仅需五分鐘时，您也知道是否需要快点趕到登機口。","englishTokens":[{"type":"text","text":"When it's only a five minute walk and you also know if you need to hurry if you need to rush to your gate."}]}],"tags":[]},{"id":"scene-89","no":"89","titleZh":"第 89 段","titleEn":"Part 89","sentences":[{"en":"I usually eat something while I wait at my gate.","tc":"我通常在門口等候时吃点东西。","englishTokens":[{"type":"text","text":"I usually eat something while I wait at my gate."}]},{"en":"I wait at my boarding gate.","tc":"我在登機口等候。","englishTokens":[{"type":"text","text":"I wait at my boarding gate."}]},{"en":"It can be long sometimes, so I usually get some dessert.","tc":"有时會很長，所以我通常會吃一些甜点。","englishTokens":[{"type":"text","text":"It can be long sometimes, so I usually "},{"type":"usage","text":"get","targetId":"usage-get-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-89-003-001"},{"type":"text","text":" some dessert."}]},{"en":"This one was a sweet bean dessert in Thailand.","tc":"這是泰國的一種甜豆甜点。","englishTokens":[{"type":"text","text":"This one was a sweet bean dessert in Thailand."}]}],"tags":[]},{"id":"scene-90","no":"90","titleZh":"第 90 段","titleEn":"Part 90","sentences":[{"en":"It was so sweet.","tc":"真是太甜蜜了。","englishTokens":[{"type":"text","text":"It was so sweet."}]},{"en":"I loved it.","tc":"我喜歡它。","englishTokens":[{"type":"text","text":"I loved it."}]},{"en":"I'm curious.","tc":"我很好奇。","englishTokens":[{"type":"text","text":"I'm curious."}]},{"en":"Have you ever tried one of these little sweet treats?","tc":"你嘗過這些小甜品嗎？","englishTokens":[{"type":"usage","text":"Have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-90-004-001"},{"type":"text","text":" you ever tried one of these little sweet treats?"}]}],"tags":[]},{"id":"scene-91","no":"91","titleZh":"第 91 段","titleEn":"Part 91","sentences":[{"en":"What do you think of them?","tc":"你對他們有何看法？","englishTokens":[{"type":"text","text":"What do you think of them?"}]},{"en":"Before boarding, I always go to the bathroom.","tc":"登機前，我總是去洗手間。","englishTokens":[{"type":"text","text":"Before boarding, I always go to the bathroom."}]},{"en":"I make sure I have my two bags.","tc":"我確保我有两個包。","englishTokens":[{"type":"text","text":"I "},{"type":"usage","text":"make","targetId":"usage-make-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-91-003-001"},{"type":"text","text":" sure I "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-91-003-002"},{"type":"text","text":" my two bags."}]},{"en":"And then we get on the airport shuttle bus.","tc":"然後我們就坐上了機場大巴。","englishTokens":[{"type":"text","text":"And then we "},{"type":"usage","text":"get","targetId":"usage-get-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-91-004-001"},{"type":"text","text":" on the "},{"type":"word","text":"airport","targetId":"word-airport","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-91-004-002"},{"type":"text","text":" shuttle bus."}]}],"tags":[]},{"id":"scene-92","no":"92","titleZh":"第 92 段","titleEn":"Part 92","sentences":[{"en":"This shuttle drives us to the airplane.","tc":"這趟班車送我們去飛機。","englishTokens":[{"type":"text","text":"This shuttle drives us to the airplane."}]},{"en":"Sometimes we take a shuttle to a plane and sometimes you just go straight through and board the plane.","tc":"有时我們乘坐班車去飛機，有时您直接穿過并登機。","englishTokens":[{"type":"text","text":"Sometimes we "},{"type":"usage","text":"take","targetId":"usage-take-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-92-002-001"},{"type":"text","text":" a shuttle to a plane and sometimes you just go straight through and board the plane."}]},{"en":"I prefer going straight to the plane, but sometimes you have to take a shuttle.","tc":"我更喜歡直接去飛機，但有时你必須乘坐班車。","englishTokens":[{"type":"text","text":"I prefer going straight to the plane, but sometimes you "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-92-003-001"},{"type":"text","text":" to "},{"type":"usage","text":"take","targetId":"usage-take-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-92-003-002"},{"type":"text","text":" a shuttle."}]},{"en":"The shuttle took all of the passengers to the plane and then we waited in line to board.","tc":"班車将所有乘客送上飛機，然後我們排队等候登機。","englishTokens":[{"type":"text","text":"The shuttle took all of the passengers to the plane and then we waited in line to board."}]}],"tags":[]},{"id":"scene-93","no":"93","titleZh":"第 93 段","titleEn":"Part 93","sentences":[{"en":"We had to climb stairs to board our plane.","tc":"我們必須爬樓梯才能登機。","englishTokens":[{"type":"text","text":"We had to climb stairs to board our plane."}]},{"en":"We walked through the aisle of the plane and we put our luggage in the overhead bin right above our seats.","tc":"我們走過飛機的過道，把行李放在座位上方的頭顶行李箱里。","englishTokens":[{"type":"text","text":"We walked through the aisle of the plane and we put our "},{"type":"word","text":"luggage","targetId":"word-luggage","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-93-002-001"},{"type":"text","text":" in the overhead bin right above our seats."}]},{"en":"Here I am sitting in the aisle seat because I'm right next to the aisle.","tc":"我坐在靠過道的座位上，因為我就在過道旁邊。","englishTokens":[{"type":"text","text":"Here I am sitting in the aisle seat because I'm right next to the aisle."}]},{"en":"This is my personal favorite seat because I can get up and go to the bathroom however many times I need and I use the bathroom a lot.","tc":"這是我個人最喜歡的座位，因為我可以起身去洗手間，無论我需要多少次，而且我經常使用洗手間。","englishTokens":[{"type":"text","text":"This is my personal favorite seat because I can "},{"type":"usage","text":"get","targetId":"usage-get-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-93-004-001"},{"type":"text","text":" up and go to the bathroom however many times I need and I use the bathroom a lot."}]}],"tags":[]},{"id":"scene-94","no":"94","titleZh":"第 94 段","titleEn":"Part 94","sentences":[{"en":"I love a plane with screens where I can watch movies.","tc":"我喜歡有屏幕的飛機，可以在上面看電影。","englishTokens":[{"type":"text","text":"I love a plane with screens where I can watch movies."}]},{"en":"This plane was super empty.","tc":"這架飛機非常空。","englishTokens":[{"type":"text","text":"This plane was super empty."}]},{"en":"So, I got a window seat.","tc":"所以，我得到了一個靠窗的座位。","englishTokens":[{"type":"text","text":"So, I got a window seat."}]},{"en":"The aisle seat and the middle seat were both empty.","tc":"過道座位和中間座位都空了。","englishTokens":[{"type":"text","text":"The aisle seat and the middle seat were both empty."}]}],"tags":[]},{"id":"scene-95","no":"95","titleZh":"第 95 段","titleEn":"Part 95","sentences":[{"en":"So, I chose the window seat.","tc":"所以，我選擇了靠窗的座位。","englishTokens":[{"type":"text","text":"So, I chose the window seat."}]},{"en":"And then we are ready to take off.","tc":"然後我們就准備起飛了。","englishTokens":[{"type":"text","text":"And then we are ready to "},{"type":"phrase","text":"take off","targetId":"phrase-take-off","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-378-01"},{"type":"text","text":"."}]},{"en":"The plane drives on the runway for a little while and once it gains enough speed, we take off and then I'm ready to put on my sleep mask and take a long nap.","tc":"飛機在跑道上行驶了一會兒，一旦获得足夠的速度，我們就起飛，然後我准備戴上睡眠面罩，小睡一會兒。","englishTokens":[{"type":"text","text":"The plane drives on the runway for a little while and once it gains enough speed, we "},{"type":"phrase","text":"take off","targetId":"phrase-take-off","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-95-003-001"},{"type":"text","text":" and then I'm ready to put on my sleep mask and "},{"type":"usage","text":"take","targetId":"usage-take-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-95-003-002"},{"type":"text","text":" a long nap."}]},{"en":"The best way to spend a flight is sleeping through it.","tc":"度過飛行时光的最佳方式就是在旅途中睡覺。","englishTokens":[{"type":"text","text":"The best way to spend a flight is sleeping through it."}]}],"tags":[]},{"id":"scene-96","no":"96","titleZh":"第 96 段","titleEn":"Part 96","sentences":[{"en":"On long flights, they normally give you a pillow and a blanket.","tc":"在長途航班上，他們通常會為您提供枕頭和毯子。","englishTokens":[{"type":"text","text":"On long flights, they normally give you a pillow and a blanket."}]},{"en":"And you get to watch movies on the flight.","tc":"您还可以在飛機上觀看電影。","englishTokens":[{"type":"text","text":"And you "},{"type":"usage","text":"get","targetId":"usage-get-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-96-002-001"},{"type":"text","text":" to watch movies on the flight."}]},{"en":"On long flights, I always bring my neck pillow and I like watching the screen to see how far we have traveled.","tc":"在長途飛行中，我總是帶上颈枕，我喜歡看屏幕來了解我們已經飛行了多遠。","englishTokens":[{"type":"text","text":"On long flights, I always bring my neck pillow and I like watching the screen to see how far we "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-96-003-001"},{"type":"text","text":" traveled."}]},{"en":"I also like looking at the world and learning about different countries that are new to me.","tc":"我也喜歡看看世界，了解對我來說陌生的不同國家。","englishTokens":[{"type":"text","text":"I also like looking at the world and learning about different countries that are new to me."}]}],"tags":[]},{"id":"scene-97","no":"97","titleZh":"第 97 段","titleEn":"Part 97","sentences":[{"en":"They were new to me before.","tc":"他們以前對我來說是新的。","englishTokens":[{"type":"text","text":"They were new to me before."}]},{"en":"During my flights, I like to work on my computer.","tc":"在飛行期間，我喜歡在電腦上工作。","englishTokens":[{"type":"text","text":"During my flights, I like to work on my computer."}]},{"en":"And during longer flights, I love how they tint out the windows so that even if it's sunny outside, it will seem like it's nighttime.","tc":"在長途飛行中，我喜歡它們给車窗染色的方式，這樣即使外面陽光明媚，也看起來像是在夜間。","englishTokens":[{"type":"text","text":"And during longer flights, I love how they tint out the windows so that even if it's sunny outside, it will seem like it's nighttime."}]},{"en":"It makes the sun look very pretty.","tc":"它使太陽看起來非常漂亮。","englishTokens":[{"type":"text","text":"It makes the sun look very pretty."}]}],"tags":[]},{"id":"scene-98","no":"98","titleZh":"第 98 段","titleEn":"Part 98","sentences":[{"en":"Then the sun rises and I think it's almost time to land.","tc":"然後太陽升起，我想差不多該着陆了。","englishTokens":[{"type":"text","text":"Then the sun rises and I think it's almost time to land."}]},{"en":"Finally, I wait my turn to get off the plane.","tc":"最後，我等待着下飛機。","englishTokens":[{"type":"text","text":"Finally, I wait my turn to "},{"type":"usage","text":"get","targetId":"usage-get-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-98-002-001"},{"type":"text","text":" off the plane."}]},{"en":"I get my bags down from the overhead bin and we walk out.","tc":"我从頭顶行李箱上取下行李，然後走出去。","englishTokens":[{"type":"text","text":"I "},{"type":"usage","text":"get","targetId":"usage-get-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-98-003-001"},{"type":"text","text":" my bags down from the overhead bin and we walk out."}]},{"en":"There is normally an escalator to get to immigration or passport control.","tc":"通常有自動扶梯前往出入境或護照檢查處。","englishTokens":[{"type":"text","text":"There is normally an escalator to "},{"type":"usage","text":"get","targetId":"usage-get-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-98-004-001"},{"type":"text","text":" to immigration or "},{"type":"word","text":"passport","targetId":"word-passport","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-98-004-002"},{"type":"text","text":" control."}]}],"tags":[]},{"id":"scene-99","no":"99","titleZh":"第 99 段","titleEn":"Part 99","sentences":[{"en":"You scan your passport and maybe talk to an immigration officer, and then you are in the country you want to visit.","tc":"您扫描您的護照，也许还可以與移民官員交談，然後您就到達了您想要访問的國家。","englishTokens":[{"type":"text","text":"You scan your "},{"type":"word","text":"passport","targetId":"word-passport","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-99-001-001"},{"type":"text","text":" and maybe talk to an immigration officer, and then you are in the country you want to visit."}]},{"en":"But if you have a layover, you normally still have to go through passport control depending on the country, but you just don't leave the airport.","tc":"但是，如果您需要中转，通常仍然需要根據國家/地區进行護照檢查，但您只需不要離開機場即可。","englishTokens":[{"type":"text","text":"But if you "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-99-002-001"},{"type":"text","text":" a layover, you normally still "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-99-002-002"},{"type":"text","text":" "},{"type":"phrase","text":"to go","targetId":"phrase-to-go","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-99-002-003"},{"type":"text","text":" through "},{"type":"word","text":"passport","targetId":"word-passport","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-99-002-004"},{"type":"text","text":" control depending on the country, but you just don't leave the "},{"type":"word","text":"airport","targetId":"word-airport","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-99-002-005"},{"type":"text","text":"."}]},{"en":"You stay.","tc":"你留下來。","englishTokens":[{"type":"text","text":"You stay."}]},{"en":"When I have layovers, I usually stop by the food court where I can find pizza, Mexican food, Chinese food, or McDonald's.","tc":"當我中途停留时，我通常會去美食广場，在那里我可以找到披萨、墨西哥菜、中餐或麥當劳。","englishTokens":[{"type":"text","text":"When I "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-99-004-001"},{"type":"text","text":" layovers, I usually stop by the food court where I can find pizza, Mexican food, Chinese food, or McDonald's."}]}],"tags":[]},{"id":"scene-100","no":"100","titleZh":"第 100 段","titleEn":"Part 100","sentences":[{"en":"This time I got an orange smoothie and a croissant sandwich.","tc":"這次我得到了一份橙子冰沙和一個羊角面包三明治。","englishTokens":[{"type":"text","text":"This time I got an orange smoothie and a croissant sandwich."}]},{"en":"I eat during my layovers.","tc":"我在中途停留期間吃东西。","englishTokens":[{"type":"text","text":"I eat during my layovers."}]},{"en":"Then I make my way to my gate again.","tc":"然後我再次走向我的大門。","englishTokens":[{"type":"text","text":"Then I "},{"type":"usage","text":"make","targetId":"usage-make-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-100-003-001"},{"type":"text","text":" my way to my gate again."}]},{"en":"Now, this gate is to get me to my final destination, not just my layover.","tc":"現在，這個登機口是為了讓我到達最終目的地，而不仅仅是我的中途停留。","englishTokens":[{"type":"text","text":"Now, this gate is to "},{"type":"usage","text":"get","targetId":"usage-get-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-100-004-001"},{"type":"text","text":" me to my final destination, not just my layover."}]}],"tags":[]},{"id":"scene-101","no":"101","titleZh":"第 101 段","titleEn":"Part 101","sentences":[{"en":"I saw these super cool suitcases.","tc":"我看到了這些超酷的手提箱。","englishTokens":[{"type":"text","text":"I saw these super cool suitcases."}]},{"en":"You can drive and sit down on them.","tc":"你可以開車，也可以坐在上面。","englishTokens":[{"type":"text","text":"You can drive and sit down on them."}]},{"en":"That way, you don't need to walk.","tc":"這樣，你就不需要走路了。","englishTokens":[{"type":"text","text":"That way, you don't need to walk."}]},{"en":"Now, sometimes your next gate is at a different terminal.","tc":"現在，有时您的下一個登機口位于不同的航站樓。","englishTokens":[{"type":"text","text":"Now, sometimes your next gate is at a different "},{"type":"word","text":"terminal","targetId":"word-terminal","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-404-01"},{"type":"text","text":"."}]}],"tags":[]},{"id":"scene-102","no":"102","titleZh":"第 102 段","titleEn":"Part 102","sentences":[{"en":"Maybe you're at terminal 1 and your next flight leaves at terminal 4, maybe terminal A and you need to get to terminal F depending on the airport.","tc":"也许您在1號航站樓，下一趟航班从4號航站樓起飛，也可能是A航站樓，您需要前往F航站樓，具體取決于機場。","englishTokens":[{"type":"text","text":"Maybe you're at "},{"type":"word","text":"terminal","targetId":"word-terminal","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-102-001-001"},{"type":"text","text":" 1 and your next flight leaves at "},{"type":"word","text":"terminal","targetId":"word-terminal","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-102-001-002"},{"type":"text","text":" 4, maybe "},{"type":"word","text":"terminal","targetId":"word-terminal","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-102-001-003"},{"type":"text","text":" A and you need to "},{"type":"usage","text":"get","targetId":"usage-get-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-102-001-004"},{"type":"text","text":" to "},{"type":"word","text":"terminal","targetId":"word-terminal","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-102-001-005"},{"type":"text","text":" F depending on the "},{"type":"word","text":"airport","targetId":"word-airport","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-102-001-006"},{"type":"text","text":"."}]},{"en":"So you need to take the airport train or airport shuttle.","tc":"所以你需要乘坐機場火車或機場班車。","englishTokens":[{"type":"text","text":"So you need to "},{"type":"usage","text":"take","targetId":"usage-take-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-102-002-001"},{"type":"text","text":" the "},{"type":"word","text":"airport","targetId":"word-airport","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-102-002-002"},{"type":"text","text":" train or "},{"type":"word","text":"airport","targetId":"word-airport","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-102-002-003"},{"type":"text","text":" shuttle."}]},{"en":"So, you look at the signs and you follow them to the airport shuttle and that takes you to your next terminal.","tc":"因此，您查看標志并按照它們前往機場班車，然後将您帶到下一個航站樓。","englishTokens":[{"type":"text","text":"So, you look at the signs and you follow them to the "},{"type":"word","text":"airport","targetId":"word-airport","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-102-003-001"},{"type":"text","text":" shuttle and that takes you to your next "},{"type":"word","text":"terminal","targetId":"word-terminal","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-102-003-002"},{"type":"text","text":"."}]},{"en":"This flight left from terminal 4.","tc":"該航班从4號航站樓起飛。","englishTokens":[{"type":"text","text":"This flight left from "},{"type":"word","text":"terminal","targetId":"word-terminal","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-102-004-001"},{"type":"text","text":" 4."}]}],"tags":[]},{"id":"scene-103","no":"103","titleZh":"第 103 段","titleEn":"Part 103","sentences":[{"en":"So, I took the shuttle from terminal 1 to terminal 4.","tc":"于是，我乘坐班車从1號航站樓前往4號航站樓。","englishTokens":[{"type":"text","text":"So, I took the shuttle from "},{"type":"word","text":"terminal","targetId":"word-terminal","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-103-001-001"},{"type":"text","text":" 1 to "},{"type":"word","text":"terminal","targetId":"word-terminal","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-103-001-002"},{"type":"text","text":" 4."}]},{"en":"I love walking on the moving walkway or the moving sidewalks.","tc":"我喜歡在自動人行道或自動人行道上行走。","englishTokens":[{"type":"text","text":"I love walking on the moving walkway or the moving sidewalks."}]},{"en":"I feel like I'm flying here.","tc":"我感覺我正在飛翔。","englishTokens":[{"type":"text","text":"I feel like I'm flying here."}]},{"en":"I looked so tired I barely got any sleep.","tc":"我看起來很累，几乎沒有睡覺。","englishTokens":[{"type":"text","text":"I looked so tired I barely got any sleep."}]}],"tags":[]},{"id":"scene-104","no":"104","titleZh":"第 104 段","titleEn":"Part 104","sentences":[{"en":"So, I ordered a juice and I edited for a little while.","tc":"所以，我点了一杯果汁，编辑了一會兒。","englishTokens":[{"type":"text","text":"So, I ordered a juice and I edited for a little while."}]},{"en":"Then it's time to wait at your gate.","tc":"然後就該在門口等候了。","englishTokens":[{"type":"text","text":"Then it's time to wait at your gate."}]},{"en":"You don't want to wait somewhere else because you might miss your flight.","tc":"您不想在其他地方等待，因為您可能會錯過航班。","englishTokens":[{"type":"text","text":"You don't want to wait somewhere else because you might miss your flight."}]},{"en":"Finally, you land at your final destination.","tc":"最後，您降落在最終目的地。","englishTokens":[{"type":"text","text":"Finally, you land at your final destination."}]}],"tags":[]},{"id":"scene-105","no":"105","titleZh":"第 105 段","titleEn":"Part 105","sentences":[{"en":"Whether that's home or a place you want to travel or the home of someone you love.","tc":"無论是家、您想去旅行的地方还是您所愛之人的家。","englishTokens":[{"type":"text","text":"Whether that's home or a place you want to travel or the home of someone you love."}]},{"en":"But if you checked a bag, then you need to go get your bag at the luggage carousel.","tc":"但如果您托運了行李，那麼您需要前往行李传送帶领取行李。","englishTokens":[{"type":"text","text":"But if you checked a bag, then you need "},{"type":"phrase","text":"to go","targetId":"phrase-to-go","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-105-002-001"},{"type":"text","text":" "},{"type":"usage","text":"get","targetId":"usage-get-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-105-002-002"},{"type":"text","text":" your bag at the "},{"type":"word","text":"luggage","targetId":"word-luggage","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-105-002-003"},{"type":"text","text":" carousel."}]},{"en":"You check your gates and your flight to make sure it's the same as yours, and you wait until you see your luggage pass by.","tc":"你檢查登機口和航班，確保與你的航班相同，然後等待，直到看到你的行李經過。","englishTokens":[{"type":"text","text":"You check your gates and your flight to "},{"type":"usage","text":"make","targetId":"usage-make-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-105-003-001"},{"type":"text","text":" sure it's the same as yours, and you wait until you see your "},{"type":"word","text":"luggage","targetId":"word-luggage","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-105-003-002"},{"type":"text","text":" pass by."}]},{"en":"I don't know about you, but I love my airport outfits.","tc":"我不了解你，但我喜歡我的機場服装。","englishTokens":[{"type":"text","text":"I don't know about you, but I love my "},{"type":"word","text":"airport","targetId":"word-airport","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-105-004-001"},{"type":"text","text":" outfits."}]}],"tags":[]},{"id":"scene-106","no":"106","titleZh":"第 106 段","titleEn":"Part 106","sentences":[{"en":"They are super cozy.","tc":"他們非常舒适。","englishTokens":[{"type":"text","text":"They are super cozy."}]},{"en":"Here's one.","tc":"這是一個。","englishTokens":[{"type":"text","text":"Here's one."}]},{"en":"A baggy shirt, my high bun, and some very loose pants.","tc":"一件寬松的衬衫，我的高發髻，还有一些非常寬松的裤子。","englishTokens":[{"type":"text","text":"A baggy shirt, my high bun, and some very loose pants."}]},{"en":"Now, here's a little story time of when I lost my passport in Beijing.","tc":"現在，這是我在北京丢失護照的小故事时間。","englishTokens":[{"type":"text","text":"Now, here's a little story time of when I lost my "},{"type":"word","text":"passport","targetId":"word-passport","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-106-004-001"},{"type":"text","text":" in Beijing."}]}],"tags":[]},{"id":"scene-107","no":"107","titleZh":"第 107 段","titleEn":"Part 107","sentences":[{"en":"Have you ever lost your passport?","tc":"您曾經丢失過護照嗎？","englishTokens":[{"type":"usage","text":"Have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-107-001-001"},{"type":"text","text":" you ever lost your "},{"type":"word","text":"passport","targetId":"word-passport","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-107-001-002"},{"type":"text","text":"?"}]},{"en":"I am at the airport.","tc":"我在機場。","englishTokens":[{"type":"text","text":"I am at the "},{"type":"word","text":"airport","targetId":"word-airport","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-107-002-001"},{"type":"text","text":"."}]},{"en":"This is my airport outfit.","tc":"這是我的機場服装。","englishTokens":[{"type":"text","text":"This is my "},{"type":"word","text":"airport","targetId":"word-airport","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-107-003-001"},{"type":"text","text":" outfit."}]},{"en":"What do you wear to the airport?","tc":"你去機場穿什麼？","englishTokens":[{"type":"text","text":"What do you wear to the "},{"type":"word","text":"airport","targetId":"word-airport","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-107-004-001"},{"type":"text","text":"?"}]}],"tags":[]},{"id":"scene-108","no":"108","titleZh":"第 108 段","titleEn":"Part 108","sentences":[{"en":"I feel so comfy.","tc":"我感覺很舒服。","englishTokens":[{"type":"text","text":"I feel so comfy."}]},{"en":"Like I'm wearing a blanket.","tc":"就像我穿着毯子一樣。","englishTokens":[{"type":"text","text":"Like I'm wearing a blanket."}]},{"en":"I have two big backpacks.","tc":"我有两個大背包。","englishTokens":[{"type":"text","text":"I "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-108-003-001"},{"type":"text","text":" two big backpacks."}]},{"en":"One is a carry on and the other one is a personal item.","tc":"一件是随身携帶物品，另一件是個人物品。","englishTokens":[{"type":"text","text":"One is a carry on and the other one is a personal item."}]}],"tags":[]},{"id":"scene-109","no":"109","titleZh":"第 109 段","titleEn":"Part 109","sentences":[{"en":"I am at the Beijing airport, but I'm not staying here.","tc":"我在北京機場，但我不住在這里。","englishTokens":[{"type":"text","text":"I am at the Beijing "},{"type":"word","text":"airport","targetId":"word-airport","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-109-001-001"},{"type":"text","text":", but I'm not staying here."}]},{"en":"Beijing is just my layover to go to Bangkok, Thailand.","tc":"北京只是我去泰國曼谷的中转站。","englishTokens":[{"type":"text","text":"Beijing is just my layover "},{"type":"phrase","text":"to go","targetId":"phrase-to-go","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-109-002-001"},{"type":"text","text":" to Bangkok, Thailand."}]},{"en":"My final destination is Bangkok, Thailand.","tc":"我的最終目的地是泰國曼谷。","englishTokens":[{"type":"text","text":"My final destination is Bangkok, Thailand."}]},{"en":"But don't worry, I will be back to Beijing in one week to visit the city.","tc":"不過別担心，一周後我就會回北京参觀這座城市。","englishTokens":[{"type":"text","text":"But don't worry, I will be back to Beijing in one week to visit the city."}]}],"tags":[]},{"id":"scene-110","no":"110","titleZh":"第 110 段","titleEn":"Part 110","sentences":[{"en":"My flight from Tijuana to Beijing was 12 hours long.","tc":"我从蒂华纳飛往北京的航班飛行了12個小时。","englishTokens":[{"type":"text","text":"My flight from Tijuana to Beijing was 12 hours long."}]},{"en":"I'm super jet lagged and I still have another 4 hours.","tc":"我时差太厉害了，还有4個小时。","englishTokens":[{"type":"text","text":"I'm super jet lagged and I still "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-110-002-001"},{"type":"text","text":" another 4 hours."}]},{"en":"And actually, I was so stressed out about getting Wi-Fi to work on my videos, editing, and answering emails that I forgot my passport.","tc":"事實上，我對使用Wi-Fi來處理視頻、编辑和回複電子邮件感到非常緊張，以至于我忘记了護照。","englishTokens":[{"type":"text","text":"And actually, I was so stressed out about getting Wi-Fi to work on my videos, editing, and answering emails that I forgot my "},{"type":"word","text":"passport","targetId":"word-passport","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-110-003-001"},{"type":"text","text":"."}]},{"en":"I left it on the table and I walked away searching for Wi-Fi.","tc":"我把它放在桌子上，然後走開去尋找Wi-Fi。","englishTokens":[{"type":"text","text":"I left it on the table and I walked away searching for Wi-Fi."}]}],"tags":[]},{"id":"scene-111","no":"111","titleZh":"第 111 段","titleEn":"Part 111","sentences":[{"en":"I realized I lost my passport and I ran desperately looking and asking everyone.","tc":"我意識到我丢了護照，我拼命地跑去尋找并询問每個人。","englishTokens":[{"type":"text","text":"I realized I lost my "},{"type":"word","text":"passport","targetId":"word-passport","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-111-001-001"},{"type":"text","text":" and I ran desperately looking and asking everyone."}]},{"en":"But nobody speaks English, so I was super stressed just a minute ago.","tc":"但沒有人會說英語，所以我一分鐘前壓力很大。","englishTokens":[{"type":"text","text":"But nobody speaks English, so I was super stressed just a minute ago."}]},{"en":"Now I'm a lot more relaxed.","tc":"現在我輕松多了。","englishTokens":[{"type":"text","text":"Now I'm a lot more "},{"type":"word","text":"relaxed","targetId":"word-relaxed","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-443-01"},{"type":"text","text":"."}]},{"en":"I don't have Wi-Fi, but now I know it could be much worse.","tc":"我沒有Wi-Fi，但現在我知道情况可能會更糟。","englishTokens":[{"type":"text","text":"I don't "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-111-004-001"},{"type":"text","text":" Wi-Fi, but now I know it could be much worse."}]}],"tags":[]},{"id":"scene-112","no":"112","titleZh":"第 112 段","titleEn":"Part 112","sentences":[{"en":"Sometimes life just teaches you lessons that you need at that moment to really appreciate what you do have and not stress about little things like Wi-Fi.","tc":"有时候，生活只是教给你當时需要的課程，讓你真正欣赏自己所擁有的，而不是為Wi-Fi這樣的小事感到壓力。","englishTokens":[{"type":"text","text":"Sometimes life just teaches you lessons that you need at that moment to really appreciate what you do "},{"type":"usage","text":"have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-112-001-001"},{"type":"text","text":" and not stress about little things like Wi-Fi."}]},{"en":"Have you ever lost your passport before?","tc":"您以前丢失過護照嗎？","englishTokens":[{"type":"usage","text":"Have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-112-002-001"},{"type":"text","text":" you ever lost your "},{"type":"word","text":"passport","targetId":"word-passport","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-112-002-002"},{"type":"text","text":" before?"}]},{"en":"All right, guys.","tc":"好吧，伙計們。","englishTokens":[{"type":"text","text":"All right, guys."}]},{"en":"Thank you so much for joining me.","tc":"非常感谢您加入我。","englishTokens":[{"type":"text","text":"Thank you so much for joining me."}]}],"tags":[]},{"id":"scene-113","no":"113","titleZh":"第 113 段","titleEn":"Part 113","sentences":[{"en":"I hope you learned some new English vocabulary, and I hope this helps you in the future if you travel and need help.","tc":"我希望您學到一些新的英語詞彙，希望這對您将來旅行并需要幫助时有所幫助。","englishTokens":[{"type":"text","text":"I hope you learned some new English vocabulary, and I hope this helps you in the future if you travel and need help."}]},{"en":"Find your passport or your gate number or your terminal.","tc":"找到您的護照或登機口號碼或航站樓。","englishTokens":[{"type":"text","text":"Find your "},{"type":"word","text":"passport","targetId":"word-passport","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-113-002-001"},{"type":"text","text":" or your gate number or your "},{"type":"word","text":"terminal","targetId":"word-terminal","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-113-002-002"},{"type":"text","text":"."}]},{"en":"If you're feeling nervous about traveling somewhere and not knowing what to do, use this video to guide you through that unknown vocabulary at airports.","tc":"如果您對去某個地方旅行感到緊張并且不知道該怎麼做，請使用此視頻來指導您了解機場中的未知詞彙。","englishTokens":[{"type":"text","text":"If you're feeling nervous about traveling somewhere and not knowing what to do, use this video to guide you through that unknown vocabulary at airports."}]},{"en":"Have a beautiful day and don't stop learning.","tc":"祝你有美好的一天，不要停止學習。","englishTokens":[{"type":"usage","text":"Have","targetId":"usage-have-item","instanceId":"marker-a2-ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary-scene-113-004-001"},{"type":"text","text":" a beautiful day and don't stop learning."}]}],"tags":[]},{"id":"scene-114","no":"114","titleZh":"第 114 段","titleEn":"Part 114","sentences":[{"en":"See you next time.","tc":"下次见。","englishTokens":[{"type":"text","text":"See you next time."}]},{"en":"Bye.","tc":"再见。","englishTokens":[{"type":"text","text":"Bye."}]},{"en":"If you liked this compilation of English essentials, then like this video and tell me what your favorite video was in the comments.","tc":"如果您喜歡這個英語精要彙编，請点讚這個視頻并在评论中告诉我您最喜歡的視頻是什麼。","englishTokens":[{"type":"text","text":"If you liked this compilation of English essentials, then like this video and tell me what your favorite video was in the comments."}]},{"en":"Don't forget to subscribe and remember, never stop learning.","tc":"別忘了訂阅并记住，學習永不停歇。","englishTokens":[{"type":"text","text":"Don't forget to subscribe and remember, never stop learning."}]}],"tags":[]},{"id":"scene-115","no":"115","titleZh":"第 115 段","titleEn":"Part 115","sentences":[{"en":"Bye.","tc":"再见。","englishTokens":[{"type":"text","text":"Bye."}]}],"tags":[]}]`),i=[{title:"A2 重點單字",items:[{id:"word-comprehensible",lemma:"comprehensible",english:"comprehensible",kk:"/comprehensible/",partOfSpeech:"adj.",meaning:"可理解的",highlight:!0},{id:"word-phrase",lemma:"phrase",english:"phrases",kk:"/phrase/",partOfSpeech:"noun",meaning:"片語",highlight:!0},{id:"word-essential",lemma:"essential",english:"essential",kk:"/essential/",partOfSpeech:"adj.",meaning:"必要的",highlight:!0},{id:"word-native",lemma:"native",english:"native",kk:"/native/",partOfSpeech:"adj.",meaning:"母語的",highlight:!0},{id:"word-airport",lemma:"airport",english:"airport",kk:"/airport/",partOfSpeech:"noun",meaning:"機場",highlight:!0},{id:"word-passport",lemma:"passport",english:"passport",kk:"/passport/",partOfSpeech:"noun",meaning:"護照",highlight:!0},{id:"word-luggage",lemma:"luggage",english:"luggage",kk:"/luggage/",partOfSpeech:"noun",meaning:"行李",highlight:!0},{id:"word-security",lemma:"security",english:"security",kk:"/security/",partOfSpeech:"noun",meaning:"安檢",highlight:!0},{id:"word-checkpoint",lemma:"checkpoint",english:"checkpoint",kk:"/checkpoint/",partOfSpeech:"noun",meaning:"檢查站",highlight:!0},{id:"word-laptop",lemma:"laptop",english:"laptop",kk:"/laptop/",partOfSpeech:"noun",meaning:"筆電",highlight:!0},{id:"word-charger",lemma:"charger",english:"charger",kk:"/charger/",partOfSpeech:"noun",meaning:"充電器",highlight:!0},{id:"word-delayed",lemma:"delayed",english:"delayed",kk:"/delayed/",partOfSpeech:"adj.",meaning:"延誤的",highlight:!0},{id:"word-terminal",lemma:"terminal",english:"terminal",kk:"/terminal/",partOfSpeech:"noun",meaning:"航廈",highlight:!0},{id:"word-transportation",lemma:"transportation",english:"transportation",kk:"/transportation/",partOfSpeech:"noun",meaning:"交通",highlight:!0},{id:"word-relaxed",lemma:"relaxed",english:"relaxed",kk:"/relaxed/",partOfSpeech:"adj.",meaning:"放鬆的",highlight:!0},{id:"word-challenge",lemma:"challenge",english:"challenge",kk:"/challenge/",partOfSpeech:"noun",meaning:"挑戰",highlight:!0},{id:"word-grocery",lemma:"grocery",english:"grocery",kk:"/grocery/",partOfSpeech:"noun",meaning:"食品雜貨",highlight:!0},{id:"word-supermarket",lemma:"supermarket",english:"supermarkets",kk:"/supermarket/",partOfSpeech:"noun",meaning:"超市",highlight:!0}]}],r=[{id:"phrase-slow-english-podcast",phrase:"slow English podcast",meaning:"慢速英文播客",examples:[{en:"So, join me in this __slow English podcast__.",tc:"慢速英文播客"}]},{id:"phrase-take-off",phrase:"take off",meaning:"脫下；起飛",examples:[{en:"And then we are ready to __take off__.",tc:"脫下；起飛"}]},{id:"phrase-check-in",phrase:"check in",meaning:"辦理報到",examples:[{en:"I am in line to __check in__.",tc:"辦理報到"}]},{id:"phrase-to-go",phrase:"to go",meaning:"外帶",examples:[{en:"When I'm ready to check out all of my groceries, I normally try __to go__ to self checkout.",tc:"外帶"}]},{id:"phrase-grocery-store",phrase:"grocery store",meaning:"雜貨店",examples:[{en:"At the **airport**, at the __grocery store__, at the house, and in the kitchen.",tc:"雜貨店"}]},{id:"phrase-something-else",phrase:"something else",meaning:"很特別",examples:[{en:"__Something else__ that's very important, the toppers.",tc:"很特別"}]},{id:"phrase-so-far",phrase:"so far",meaning:"到目前為止",examples:[{en:"In my last video, I showed you guys what I had bought __so far__, but now I've bought even more.",tc:"到目前為止"}]}],l=[{id:"usage-get-item",word:"get",familiarMeaning:"得到；到達",usage:"表示理解、取得服務或變成某種狀態",translation:"理解；取得",examples:["So self checkout is a lot faster and I always prefer to 《get》 my fresh produce like vegetables and fruits at the local market."]},{id:"usage-have-item",word:"have",familiarMeaning:"有",usage:"表示吃喝、經歷或享有",translation:"喝；經歷；享有",examples:["And in those grocery stores, they always 《have》 free samples with no cost."]},{id:"usage-take-item",word:"take",familiarMeaning:"拿",usage:"表示脫下、進行或照顧",translation:"脫下；進行；照顧",examples:["We are going to 《take》 a flight."]},{id:"usage-make-item",word:"make",familiarMeaning:"製作",usage:"表示產生、犯下或做出",translation:"產生；犯下；做出",examples:["So dairy products 《make》 me feel very sick."]}],h=[{id:"grammar-1",sentence:"These are the words that native speakers use every day.",translation:"這些是母語人士每天使用的單詞。",points:[{label:"關係子句",text:"名詞 + who/which/that + 子句",note:"補充說明前面的名詞。"}]},{id:"grammar-2",sentence:"Today I want to talk about grocery stores and supermarkets.",translation:"今天我想談談雜貨店和超市。",points:[{label:"不定詞片語",text:"to + 原形動詞",note:"表示目的、計畫或想做的事。"}]},{id:"grammar-3",sentence:"If I'm with my family though, we will get a dozen eggs.",translation:"如果我和家人在一起，我們會得到一打雞蛋。",points:[{label:"條件句",text:"if + 子句 + 主要子句",note:"說明條件成立時的結果。"}]},{id:"grammar-4",sentence:"They might ask you paper or plastic or would you like a receipt?",translation:"他們可能會問您纸質还是塑料，或者您想要收據嗎？",points:[{label:"禮貌請求句",text:"could/would + 主詞 + 原形動詞",note:"讓請求更禮貌。"}]},{id:"grammar-5",sentence:"Today has been a super busy day.",translation:"今天真是超级忙碌的一天。",points:[{label:"現在完成式",text:"have/has + 過去分詞",note:"連結過去經驗和現在。"}]},{id:"grammar-6",sentence:"I have been watching Game of Thrones on this every night.",translation:"我每天晚上都在看《权力的游戏》。",points:[{label:"現在完成進行式",text:"have/has been + V-ing",note:"表示從過去持續到現在的動作或狀態。"}]}],c={level:"a2",slug:"ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary",sourcePath:"_private/tmp/originalContent/a2/ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary.json",proofreadPath:"C:/Users/Gary/Documents/Slowy_Learning_Eng/_private/tmp/step1/a2/ch26-100-essential-english-words-for-daily-life-slow-english-vocabulary.md"},y={videoId:e,slug:t,level:"a2",title:s,youtubeUrl:n,header:o,scenes:a,vocabGroups:i,phrases:r,usages:l,breakdowns:h,sourceTraceability:c};export{h as breakdowns,y as default,o as header,g as level,r as phrases,a as scenes,t as slug,c as sourceTraceability,s as title,l as usages,e as videoId,i as vocabGroups,n as youtubeUrl};
